import pandas as pd
import seaborn as sns


def task_func(goals, penalties):
    if goals is None or penalties is None:
        raise ValueError("goals and penalties must not be None")

    try:
        goals = list(goals)
        penalties = list(penalties)
    except TypeError as exc:
        raise TypeError("goals and penalties must be iterable") from exc

    if len(goals) != len(penalties):
        raise ValueError("goals and penalties must have the same length")

    data = pd.DataFrame(
        {
            "Team": [f"Team {i}" for i in range(1, len(goals) + 1)],
            "Goals": goals,
            "Penalties": penalties,
        }
    )

    if len(data) > 0:
        if not pd.api.types.is_numeric_dtype(data["Goals"]):
            raise TypeError("goals must contain numeric values")
        if not pd.api.types.is_numeric_dtype(data["Penalties"]):
            raise TypeError("penalties must contain numeric values")

        if data[["Goals", "Penalties"]].isna().any().any():
            raise ValueError("goals and penalties must not contain missing values")

    plot = sns.pairplot(
        data,
        vars=["Goals", "Penalties"],
        hue="Team",
    )

    return data, plot

