import re
import os
def task_func(request):
    from urllib.parse import urlsplit, unquote

    def response(status, body):
        return f"HTTP/1.1 {status}\r\n\r\n{body}"

    if not isinstance(request, str) or not request.strip():
        return response("400 Bad Request", "Bad Request")

    request_line = request.splitlines()[0].strip()
    match = re.fullmatch(
        r"GET[ \t]+(\S+)[ \t]+HTTP/\d+(?:\.\d+)?",
        request_line,
    )
    if not match:
        return response("400 Bad Request", "Bad Request")

    target = match.group(1)
    if any(ord(char) < 32 or ord(char) == 127 for char in target):
        return response("400 Bad Request", "Bad Request")

    try:
        parsed = urlsplit(target)
    except ValueError:
        return response("400 Bad Request", "Bad Request")

    if parsed.scheme or parsed.netloc:
        return response("400 Bad Request", "Bad Request")

    try:
        path = unquote(parsed.path)
    except Exception:
        return response("400 Bad Request", "Bad Request")

    if not path or path == "/":
        return response("404 Not Found", "File not found")

    if "\x00" in path or "\\" in path or "//" in path:
        return response("400 Bad Request", "Bad Request")

    relative_path = path.lstrip("/")
    if not relative_path or any(part == ".." for part in relative_path.split("/")):
        return response("400 Bad Request", "Bad Request")

    server_dir = os.path.realpath(os.getcwd())
    file_path = os.path.realpath(os.path.join(server_dir, relative_path))

    try:
        if os.path.commonpath((server_dir, file_path)) != server_dir:
            return response("400 Bad Request", "Bad Request")
    except ValueError:
        return response("400 Bad Request", "Bad Request")

    try:
        if not os.path.isfile(file_path):
            return response("404 Not Found", "File not found")

        with open(file_path, "rb") as file:
            content_bytes = file.read()

        content = content_bytes.decode("utf-8")
    except UnicodeDecodeError:
        return response("500 Internal Server Error", "Internal Server Error")
    except OSError:
        return response("500 Internal Server Error", "Internal Server Error")

    return (
        "HTTP/1.1 200 OK\r\n"
        f"Content-Length: {len(content_bytes)}\r\n"
        "\r\n"
        f"{content}"
    )

