import numpy as np
from scipy import stats


def task_func(df, column, alpha):
    if not 0 < alpha < 1:
        raise ValueError("alpha must be between 0 and 1")

    values = np.asarray(df[column], dtype=float)

    if values.ndim != 1:
        raise ValueError("column must contain one-dimensional numeric data")
    if values.size < 3:
        raise ValueError("Shapiro-Wilk test requires at least 3 observations")
    if not np.all(np.isfinite(values)):
        raise ValueError("column contains NaN or infinite values")
    if np.all(values == values[0]):
        return False

    _, p_value = stats.shapiro(values)
    return bool(p_value > alpha)

import pandas as pd
from sklearn.linear_model import LinearRegression


def task_func(df, target):
    if target not in df.columns:
        raise KeyError(f"Target column '{target}' not found in DataFrame.")

    if df.empty:
        raise ValueError("Cannot fit regression on an empty DataFrame.")

    X = df.drop(columns=[target])
    y = df[target]

    if X.shape[1] == 0:
        raise ValueError("DataFrame must contain at least one feature column.")

    model = LinearRegression()
    model.fit(X, y)

    return {"score": float(model.score(X, y))}

