def task_func(url, column_name, csv_file_path):
    downloaded = False

    try:
        urllib.request.urlretrieve(url, csv_file_path)
        downloaded = True

        with open(csv_file_path, "r", newline="", encoding="utf-8") as csv_file:
            reader = csv.DictReader(csv_file)

            if not reader.fieldnames or column_name not in reader.fieldnames:
                raise ValueError(
                    f"The provided column_name '{column_name}' does not exist in the CSV file."
                )

            counts = collections.Counter(row[column_name] for row in reader)
            return dict(counts)
    finally:
        if downloaded and os.path.exists(csv_file_path):
            os.remove(csv_file_path)

import pandas as pd
import seaborn as sns
import numpy as np
import ast


def task_func(csv_file):
    """Load e-mail data, calculate list statistics, and plot mean values."""
    try:
        data = pd.read_csv(csv_file)
    except pd.errors.EmptyDataError:
        data = pd.DataFrame(columns=["email", "list"])

    required_columns = {"email", "list"}
    missing_columns = required_columns - set(data.columns)
    if missing_columns:
        raise ValueError(
            f"Missing required columns: {', '.join(sorted(missing_columns))}"
        )

    records = []

    for _, row in data.iterrows():
        value = row["list"]

        if value is None or (
            not isinstance(value, (list, tuple))
            and (pd.isna(value) if not pd.api.types.is_scalar(value) else bool(pd.isna(value)))
        ):
            raise ValueError("Missing list value encountered.")

        if isinstance(value, str):
            try:
                value = ast.literal_eval(value)
            except (SyntaxError, ValueError) as exc:
                raise ValueError(f"Malformed list value: {value!r}") from exc

        if not isinstance(value, (list, tuple)):
            raise ValueError(f"Expected a list, got {type(value).__name__}.")

        parsed_list = list(value)

        try:
            numeric_values = np.asarray(parsed_list, dtype=float)
        except (TypeError, ValueError) as exc:
            raise ValueError("List contains non-numeric values.") from exc

        if numeric_values.size == 0:
            total = 0
            mean = np.nan
            std = np.nan
        else:
            total = np.sum(numeric_values)
            mean = np.mean(numeric_values)
            std = np.std(numeric_values)

        records.append(
            {
                "email": row["email"],
                "list": parsed_list,
                "sum": total,
                "mean": mean,
                "std": std,
            }
        )

    result = pd.DataFrame(
        records,
        columns=["email", "list", "sum", "mean", "std"],
    )

    ax = sns.histplot(data=result, x="mean")
    return result, ax

