import pandas as pd
import numpy as np
import matplotlib.pyplot as plt


def task_func(start_time, end_time, step, trend, seed=42):
    try:
        start = pd.Timestamp(pd.to_datetime(start_time))
        end = pd.Timestamp(pd.to_datetime(end_time))
    except Exception as exc:
        raise ValueError("Invalid start_time or end_time") from exc

    if pd.isna(start) or pd.isna(end):
        raise ValueError("Invalid start_time or end_time")

    try:
        if start > end:
            raise ValueError("start_time must not be later than end_time")
    except TypeError as exc:
        raise ValueError("start_time and end_time must be comparable") from exc

    if isinstance(step, bool):
        raise ValueError("step must be positive")

    try:
        offset = pd.tseries.frequencies.to_offset(step)
    except Exception as exc:
        raise ValueError("Invalid step") from exc

    if getattr(offset, "n", 1) <= 0:
        raise ValueError("step must be positive")

    if isinstance(trend, bool) or not isinstance(trend, numbers.Real):
        raise ValueError("trend must be numeric")

    try:
        timestamps = pd.date_range(start=start, end=end, freq=offset)
    except Exception as exc:
        raise ValueError("Unable to generate timestamps") from exc

    if len(timestamps) == 0:
        timestamps = pd.DatetimeIndex([start])

    rng = np.random.default_rng(seed)
    values = rng.normal(size=len(timestamps))
    values += float(trend) * np.arange(len(timestamps))

    _, ax = plt.subplots()
    ax.plot(timestamps, values)
    ax.set_xlabel("Time")
    ax.set_ylabel("Value")

    return ax

