import pandas as pd
from itertools import combinations
# Constants
MIN_PERCENTAGE = 0.75


def task_func(data, cols, percentage):
    if not isinstance(data, pd.DataFrame):
        raise TypeError("data must be a pandas DataFrame")

    if isinstance(percentage, bool) or not isinstance(percentage, (int, float)):
        raise TypeError("percentage must be numeric")
    if not 0 <= percentage <= 1:
        raise ValueError("percentage must be between 0 and 1")

    cols = list(dict.fromkeys(cols))

    missing = [col for col in cols if col not in data.columns]
    if missing:
        raise KeyError(f"Columns not found: {missing}")

    if len(cols) < 2:
        return []

    non_numeric = [
        col for col in cols
        if not pd.api.types.is_numeric_dtype(data[col])
    ]
    if non_numeric:
        raise TypeError(f"Columns must be numeric: {non_numeric}")

    corr_combinations = []

    for col1, col2 in combinations(cols, 2):
        correlation = data[[col1, col2]].corr().iloc[0, 1]
        if pd.notna(correlation) and abs(correlation) > percentage:
            corr_combinations.append((col1, col2))

    return corr_combinations

