def task_func(df, target_values=[1, 3, 4]):
    cleaned_df = df.copy()

    def is_target_value(value):
        try:
            return bool(value in target_values)
        except (TypeError, ValueError):
            return False

    for column_index in range(cleaned_df.shape[1]):
        cleaned_df.iloc[:, column_index] = cleaned_df.iloc[
