from bs4 import BeautifulSoup
import requests


def task_func(myString):
    no_url_error = "No valid URL found in the provided string."

    if not isinstance(myString, str) or not myString:
        return no_url_error

    candidates = re.findall(
        r"https?://[^\s<>'\"]+",
        myString,
        flags=re.IGNORECASE,
    )

    url = None
    for candidate in candidates:
        candidate = candidate.rstrip(".,!?;:)\\]}")

        try:
            parsed_url = urlparse(candidate)
            if (
                parsed_url.scheme.lower() in {"http", "https"}
                and parsed_url.hostname
                and parsed_url.port is not None
                or (
                    parsed_url.scheme.lower() in {"http", "https"}
                    and parsed_url.hostname
                    and ":" not in parsed_url.netloc.rsplit("@", 1)[-1]
                )
            ):
                url = candidate
                break
        except ValueError:
            continue

    if url is None:
        return no_url_error

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.RequestException:
        return f"Unable to fetch the content of the URL: {url}"

    soup = BeautifulSoup(response.content, "html.parser")
    title_tag = soup.find("title")

    if title_tag is None:
        return "No title tag found in the webpage."

    title = title_tag.get_text(strip=True)
    return title if title else "No title tag found in the webpage."

