import pandas as pd
import matplotlib.pyplot as plt


def task_func(file_path):
    if not str(file_path).lower().endswith(".csv"):
        raise ValueError("file_path must point to a .csv file")

    rows = []

    try:
        with open(file_path, "r", encoding="utf-8", newline="") as csv_file:
            reader = csv.reader(csv_file, strict=True)
            expected_length = None

            for row in reader:
                if not row:
                    continue

                if expected_length is None:
                    expected_length = len(row)
                elif len(row) != expected_length:
                    raise ValueError("CSV rows have inconsistent lengths")

                rows.append(tuple(row))
    except csv.Error as exc:
        raise ValueError("Invalid CSV format") from exc

    counts = Counter(rows)
    duplicates = {
        row: count for row, count in counts.items() if count > 1
    }

    _, ax = plt.subplots()
    ax.set_xlabel("Duplicate rows")
    ax.set_ylabel("Count")

    if duplicates:
        duplicate_rows = list(duplicates)
        columns = [
            f"column_{index + 1}"
            for index in range(len(duplicate_rows[0]))
        ]

        dataframe = pd.DataFrame(duplicate_rows, columns=columns)
        dataframe["count"] = [
            duplicates[row] for row in duplicate_rows
        ]

        labels = dataframe[columns].astype(str).agg(", ".join, axis=1)
        ax.bar(labels, dataframe["count"])
        ax.tick_params(axis="x", rotation=45)
        ax.figure.tight_layout()

    return duplicates, ax

