import requests

def task_func(myString, token):
    if not isinstance(myString, str) or not myString.strip():
        raise ValueError("myString must contain a URL")
    if not isinstance(token, str) or not token:
        raise ValueError("token is required")

    match = re.search(r"https?://[^\s<>'\"]+", myString)
    if not match:
        raise ValueError("myString contains no URL")

    url = match.group(0).rstrip(".,;:!?")
    for closing, opening in ((")", "("), ("]", "["), ("}", "{")):
        while url.endswith(closing) and url.count(closing) > url.count(opening):
            url = url[:-1]

    response = requests.post(
        "https://api.example.com/endpoint",
        json={"url": url},
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        },
        timeout=30,
    )
    response.raise_for_status()

    result = response.json()
    if not isinstance(result, dict):
        raise ValueError("The API response must be a JSON object")
    return result

