import seaborn as sns
import pandas as pd
from scipy.stats import chi2_contingency


def task_func(df1, df2, column1="feature1", column2="feature2"):
    """Merge two dataframes, perform a chi-square test, and draw a heatmap."""

    required_df1 = {"id", column1}
    required_df2 = {"id", column2}

    missing_df1 = required_df1 - set(df1.columns)
    missing_df2 = required_df2 - set(df2.columns)

    if missing_df1:
        raise KeyError(f"df1 is missing columns: {sorted(missing_df1)}")
    if missing_df2:
        raise KeyError(f"df2 is missing columns: {sorted(missing_df2)}")

    merged = pd.merge(df1, df2, on="id", how="inner")
    valid_rows = merged.dropna(subset=[column1, column2])

    if valid_rows.empty:
        raise ValueError("No valid matching rows remain after merging.")

    contingency_table = pd.crosstab(
        valid_rows[column1],
        valid_rows[column2],
    )

    if contingency_table.empty:
        raise ValueError("The contingency table is empty.")

    _, p_value, _, _ = chi2_contingency(contingency_table)
    heatmap = sns.heatmap(contingency_table, annot=True, fmt="g", cmap="Blues")

    return float(p_value), heatmap

