import pandas as pd


def task_func(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")

    frequencies = {}

    for word in text.split():
        if word.startswith("$") and any(char not in punctuation for char in word):
            frequencies[word] = frequencies.get(word, 0) + 1

    return pd.DataFrame(
