import json
import csv
import os
import base64


def task_func(raw_string, filename, output_dir):
    if not isinstance(raw_string, str):
        raise TypeError("raw_string must be a string")

    if not isinstance(filename, str) or not filename:
        raise ValueError("filename must be a non-empty string")

    if filename in (".", "..") or "/" in filename or "\\" in filename:
        raise ValueError("filename must not contain path separators")

    if not isinstance(output_dir, str) or not output_dir:
        raise ValueError("output_dir must be a non-empty string")

    try:
        decoded = base64.b64decode(raw_string, validate=True).decode("utf-8")
    except (ValueError, UnicodeDecodeError) as exc:
        raise ValueError(
            "raw_string must contain valid Base64-encoded UTF-8 text"
        ) from exc

    try:
        data = json.loads(decoded)
    except json.JSONDecodeError as exc:
        raise ValueError("Decoded content must be valid JSON") from exc

    def csv_value(value):
        if value is None:
            return ""
        if isinstance(value, (dict, list)):
            return json.dumps(value, ensure_ascii=False, separators=(",", ":"))
        return str(value)

    if isinstance(data, dict):
        fieldnames = list(data)
        rows = [{key: csv_value(data[key]) for key in fieldnames}]
    elif isinstance(data, list):
        if not all(isinstance(item, dict) for item in data):
            raise ValueError("JSON arrays must contain only objects")

        fieldnames = []
        for item in data:
            for key in item:
                if key not in fieldnames:
                    fieldnames.append(key)

        rows = [
            {key: csv_value(item.get(key)) for key in fieldnames}
            for item in data
        ]
    else:
        fieldnames = ["value"]
        rows = [{"value": csv_value(data)}]

    os.makedirs(output_dir, exist_ok=True)
    file_path = os.path.join(output_dir, filename)

    with open(file_path, "w", encoding="utf-8", newline="") as csv_file:
        writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
        if fieldnames:
            writer.writeheader()
            writer.writerows(rows)

    return str(file_path)

import pandas as pd
import re
import random


def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    columns = ["ID", "Quantity", "Code", "Price", "Product", "Description"]
    product_names = ["Apple", "Banana", "Orange", "Pear", "Grape"]
    rng = random.Random(seed)
    code_to_product = {}
    rows = []

    for line_number, line in enumerate(s.splitlines(), start=1):
        line = line.rstrip()

        if not line.strip():
            continue

        parts = re.split(r"\s+", line.strip(), maxsplit=4)
        if len(parts) != 5 or not parts[4].strip():
            raise ValueError(f"Malformed record on line {line_number}")

        record_id, quantity, code, price, description = parts

        try:
            quantity = int(quantity)
            price = int(price)
        except ValueError as exc:
            raise ValueError(
                f"Quantity and price must be integers on line {line_number}"
            ) from exc

        if code not in code_to_product:
            code_to_product[code] = rng.choice(product_names)

        rows.append(
            {
                "ID": record_id.rstrip(),
                "Quantity": quantity,
                "Code": code.rstrip(),
                "Price": price,
                "Product": code_to_product[code],
                "Description": description.rstrip(),
            }
        )

    return pd.DataFrame(rows, columns=columns)

import itertools
import math
from pandas import Series

def task_func(elements, subset_size, top_n=2):
    if subset_size < 0:
        raise ValueError("subset_size must be non-negative")
    if top_n < 0:
        raise ValueError("top_n must be non-negative")

    if subset_size == 0 or subset_size > len(elements):
        return 1, Series(dtype="int64")

    subset_sums = [
        sum(subset)
        for subset in itertools.combinations(elements, subset_size)
    ]

    product = math.prod(subset_sums)
    top_sums = Series(sorted(subset_sums, reverse=True)[:top_n])

    return product, top_sums

import subprocess
import os
import signal
import time
import csv
import io


def task_func(process_name: str) -> int:
    if not isinstance(process_name, str) or not process_name.strip():
        time.sleep(1)
        return 0

    current_pid = os.getpid()
    matching_pids = set()

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/FO", "CSV", "/NH"],
                capture_output=True,
                text=True,
                check=False,
            )

            for row in csv.reader(io.StringIO(result.stdout)):
                if len(row) < 2:
                    continue

                if row[0].strip().casefold() != process_name.casefold():
                    continue

                try:
                    pid = int(row[1].strip())
                except ValueError:
                    continue

                if pid != current_pid:
                    matching_pids.add(pid)
        else:
            result = subprocess.run(
                ["ps", "-eo", "pid=,comm="],
                capture_output=True,
                text=True,
                check=False,
            )

            for line in result.stdout.splitlines():
                parts = line.strip().split(None, 1)
                if len(parts) != 2 or parts[1] != process_name:
                    continue

                try:
                    pid = int(parts[0])
                except ValueError:
                    continue

                if pid != current_pid:
                    matching_pids.add(pid)
    except (OSError, subprocess.SubprocessError):
        matching_pids.clear()

    stopped = 0

    for pid in matching_pids:
        try:
            os.kill(pid, signal.SIGTERM)
        except (OSError, ValueError):
            continue
        stopped += 1

    time.sleep(1)
    return stopped

