import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    return "/fake/backup/path"


def task_func(directory):
    errors = []
    backup_directory = get_unique_backup_dir()

    if not os.path.exists(directory):
        return backup_directory, [f"Directory does not exist: {directory}"]

    if not os.path.isdir(directory):
        return backup_directory, [f"Path is not a directory: {directory}"]

    source_real = os.path.normcase(os.path.realpath(directory))
    backup_real = os.path.normcase(os.path.realpath(backup_directory))

    try:
        if os.path.commonpath((source_real, backup_real)) == source_real:
            return backup_directory, [
                "Backup directory cannot be inside the source directory"
            ]
    except ValueError:
        pass

    try:
        os.makedirs(backup_directory, exist_ok=True)
    except OSError as exc:
        return backup_directory, [
            f"Could not create backup directory: {exc}"
        ]

    def remove_source(path):
        try:
            if os.path.islink(path) or os.path.isfile(path):
                os.unlink(path)
            else:
                os.rmdir(path)
            return True
        except OSError as exc:
            errors.append(f"Could not remove {path}: {exc}")
            return False

    def backup_item(source, target):
        try:
            if os.path.islink(source):
                if os.path.lexists(target):
                    os.unlink(target)

                os.symlink(os.readlink(source), target)
                try:
                    shutil.copystat(source, target, follow_symlinks=False)
                except OSError:
                    if os.path.lexists(target):
                        os.unlink(target)
                    raise

                return remove_source(source)

            if os.path.isdir(source):
                if os.path.lexists(target) and (
                    not os.path.isdir(target) or os.path.islink(target)
                ):
                    raise OSError(f"Backup target is not a directory: {target}")

                os.makedirs(target, exist_ok=True)
                all_successful = True

                try:
                    entries = list(os.scandir(source))
                except OSError as exc:
                    errors.append(f"Could not read {source}: {exc}")
                    return False

                for entry in entries:
                    success = backup_item(
                        entry.path,
                        os.path.join(target, entry.name),
                    )
                    all_successful = all_successful and success

                if all_successful:
                    return remove_source(source)

                return False

            if os.path.isfile(source):
                shutil.copy2(source, target)
                return remove_source(source)

            errors.append(f"Unsupported filesystem entry: {source}")
            return False

        except (OSError, shutil.Error, TypeError, ValueError) as exc:
            errors.append(f"Could not back up {source}: {exc}")
            return False

    try:
        entries = list(os.scandir(directory))
    except OSError as exc:
        errors.append(f"Could not read source directory: {exc}")
        return backup_directory, errors

    for entry in entries:
        backup_item(
            entry.path,
            os.path.join(backup_directory, entry.name),
        )

    return backup_directory, errors

import numpy as np
import seaborn as sns


def task_func(P, T):
    if not isinstance(P, np.ndarray) or not isinstance(T, np.ndarray):
        raise TypeError("P and T must be NumPy arrays or matrices.")

    P = np.asarray(P)
    T = np.asarray(T)

    if P.ndim != 2:
        raise ValueError("P must be a 2D matrix.")
    if T.ndim != 3:
        raise ValueError("T must be a 3D tensor.")
    if P.shape[1] != T.shape[0]:
        raise ValueError("The dimensions of P and T are incompatible.")
    if any(d == 0 for d in P.shape) or any(d == 0 for d in T.shape):
        raise ValueError("P and T must not have empty dimensions.")
    if not np.issubdtype(P.dtype, np.number) or not np.issubdtype(
        T.dtype, np.number
    ):
        raise TypeError("P and T must contain numeric values.")
    if np.iscomplexobj(P) or np.iscomplexobj(T):
        raise TypeError("Complex-valued inputs are not supported.")

    result = np.einsum("ij,jkl->ikl", P, T)
    ax = sns.heatmap(result[:, :, 0])

    return result, ax

