import subprocess
import os
import shutil
import tempfile
from glob import glob


def task_func(src_folder, dst_folder):
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": "Source folder does not exist or is not a directory.",
            "failed_files": [src_folder],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
        if not os.path.isdir(dst_folder):
            raise OSError("Destination is not a directory")
    except OSError:
        return {
            "success": False,
            "message": "Destination folder could not be created.",
            "failed_files": [dst_folder],
        }

    try:
        files = [
            path
            for path in glob(os.path.join(src_folder, "*"))
            if os.path.isfile(path)
        ]
    except OSError:
        return {
            "success": False,
            "message": "Source folder could not be scanned.",
            "failed_files": [src_folder],
        }

    if not files:
        return {
            "success": True,
            "message": "No files were found to compress.",
            "failed_files": [],
        }

    same_directory = os.path.realpath(src_folder) == os.path.realpath(dst_folder)
    if same_directory:
        files.sort(key=lambda path: len(os.path.basename(path)), reverse=True)

    for source_path in files:
        filename = os.path.basename(source_path)
        destination_path = os.path.join(dst_folder, filename + ".gz")
        temporary_path = None

        try:
            file_descriptor, temporary_path = tempfile.mkstemp(
                dir=dst_folder,
                prefix=".__gzip_",
                suffix=".tmp",
            )
            os.close(file_descriptor)

            with open(temporary_path, "wb") as output_file:
                process = subprocess.Popen(
                    ["gzip", "-c", source_path],
                    stdout=output_file,
                    stderr=subprocess.PIPE,
                )
                process.communicate()

            if process.returncode != 0:
                raise subprocess.SubprocessError("gzip failed")

            shutil.move(temporary_path, destination_path)
            temporary_path = None

        except (OSError, subprocess.SubprocessError):
            failed_files.append(filename)

        finally:
            if temporary_path is not None:
                try:
                    os.remove(temporary_path)
                except OSError:
                    pass

    if failed_files:
        return {
            "success": False,
            "message": "Some files could not be compressed or moved.",
            "failed_files": failed_files,
        }

    return {
        "success": True,
        "message": "All files were compressed and moved successfully.",
        "failed_files": [],
    }

