import matplotlib.pyplot as plt


def task_func(data_file_path: str):
    try:
        data = pd.read_csv(data_file_path)
    except pd.errors.EmptyDataError:
        data = pd.DataFrame()

    numeric_data = pd.DataFrame(index=data.index)

    for column in data.columns:
        values = (
            data[column]
            .astype("string")
            .str.replace(",", "", regex=False)
        )
        numeric_data[column] = pd.to_numeric(values, errors="coerce")

    means = numeric_data.mean()
    std_devs = numeric_data.std()

    axes = []
    for column in numeric_data.columns:
        _, ax = plt.subplots()
        ax.hist(numeric_data[column].dropna())
        ax.set_title(f"Histogram of {column}")
        ax.set_xlabel(str(column))
        ax.set_ylabel("Frequency")
        axes.append(ax)

    anova_results = pd.DataFrame(columns=["F-value", "P-value"])

    if len(numeric_data.columns) >= 2:
        rows = []
        index = []

        for i in range(len(numeric_data.columns)):
            for j in range(i + 1, len(numeric_data.columns)):
                first = numeric_data.iloc[:, i].dropna()
                second = numeric_data.iloc[:, j].dropna()

                if len(first) >= 2 and len(second) >= 2:
                    f_value, p_value = f_oneway(first, second)
                else:
                    f_value, p_value = float("nan"), float("nan")

                index.append(
                    f"{numeric_data.columns[i]} vs {numeric_data.columns[j]}"
                )
                rows.append(
                    {"F-value": f_value, "P-value": p_value}
                )

        anova_results = pd.DataFrame(
            rows,
            index=index,
            columns=["F-value", "P-value"],
        )

    return means, std_devs, axes, anova_results

