import requests
import os
import zipfile
from urllib.parse import urlsplit, unquote
import ntpath
import stat


def task_func(url, destination_directory, headers=None):
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")

    if destination_directory is None:
        raise ValueError("destination_directory is required")

    destination_directory = os.fspath(destination_directory)
    os.makedirs(destination_directory, exist_ok=True)
    destination_root = os.path.realpath(destination_directory)

    url_path = unquote(urlsplit(url).path).replace("\\", "/")
    zip_filename = url_path.rstrip("/").rsplit("/", 1)[-1]
    if not zip_filename or zip_filename in {".", ".."} or "\x00" in zip_filename:
        zip_filename = "download.zip"

    zip_path = os.path.join(destination_directory, zip_filename)
    if os.path.islink(zip_path):
        raise ValueError("The destination ZIP path must not be a symbolic link")

    response = requests.get(url, headers=headers, stream=True)
    try:
        response.raise_for_status()
        with open(zip_path, "wb") as archive_file:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    archive_file.write(chunk)
    finally:
        close = getattr(response, "close", None)
        if callable(close):
            close()

    extracted_files = []

    with zipfile.ZipFile(zip_path, "r") as archive:
        for member in archive.infolist():
            member_name = member.filename.replace("\\", "/")

            if not member_name or member_name.startswith("/"):
                raise ValueError(f"Unsafe archive member: {member.filename}")

            drive, _ = ntpath.splitdrive(member_name)
            if drive or ntpath.isabs(member_name):
                raise ValueError(f"Unsafe archive member: {member.filename}")

            parts = [part for part in member_name.split("/") if part not in ("", ".")]
            if ".." in parts or (not parts and not member.is_dir()):
                raise ValueError(f"Unsafe archive member: {member.filename}")

            target_path = os.path.realpath(
                os.path.join(destination_root, *parts)
            )

            if os.path.commonpath((destination_root, target_path)) != destination_root:
                raise ValueError(f"Unsafe archive member: {member.filename}")

            mode = (member.external_attr >> 16) & 0xFFFF
            if stat.S_ISLNK(mode):
                raise ValueError(f"Symbolic links are not allowed: {member.filename}")

            if member.is_dir() or member_name.endswith("/"):
                os.makedirs(target_path, exist_ok=True)
                continue

            if os.path.realpath(zip_path) == target_path:
                raise ValueError("An archive member would overwrite the downloaded ZIP")

            os.makedirs(os.path.dirname(target_path), exist_ok=True)

            with archive.open(member, "r") as source, open(target_path, "wb") as target:
                for chunk in iter(lambda: source.read(8192), b""):
                    target.write(chunk)

            extracted_files.append("/".join(parts))

    return extracted_files

