from collections import Counter
# Constants
STOPWORDS = set(stopwords.words('english'))


def task_func(text, n=2):
    """Return counts of n-grams after removing stopwords and duplicates."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")

    if n <= 0:
        raise ValueError("n must be a positive integer")

    tokens = re.findall(r"[A-Za-z0-9]+", text.lower())
    unique_tokens = list(
        dict.fromkeys(token for token in tokens if token not in STOPWORDS)
    )

    ngrams = (
        tuple(unique_tokens[index:index + n])
        for index in range(len(unique_tokens) - n + 1)
    )

    return dict(Counter(ngrams))

