import json
import re
import pandas as pd


_NUMBER_RE = re.compile(
    r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?"
)


def _double_number(value):
    return float(value) * 2.0


def _normalize_string(value):
    stripped = value.strip()

    if _NUMBER_RE.fullmatch(stripped):
        return _double_number(stripped)

    return _NUMBER_RE.sub(
        lambda match: str(_double_number(match.group())),
        value,
    )


def _normalize_value(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return _double_number(value)
    if isinstance(value, str):
        return _normalize_string(value)
    if isinstance(value, list):
        return [_normalize_value(item) for item in value]
    return value


def task_func(json_str):
    if not isinstance(json_str, str) or not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
        if not isinstance(data, dict) or not data:
            return pd.DataFrame()

        normalized = {
            key: _normalize_value(value)
            for key, value in data.items()
        }

        columns = {}
        max_length = 0

        for key, value in normalized.items():
            column = value if isinstance(value, list) else [value]
            columns[key] = column
            max_length = max(max_length, len(column))

        for key, column in columns.items():
            if len(column) < max_length:
                columns[key] = column + [float("nan")] * (
                    max_length - len(column)
                )

        return pd.DataFrame(columns)
    except (TypeError, ValueError, OverflowError, json.JSONDecodeError):
        return pd.DataFrame()

