import pandas as pd
import csv
from difflib import ndiff


def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    def read_lines(file_path):
        try:
            with open(file_path, 'r', encoding='utf-8', newline='') as file:
                content = file.read()
        except FileNotFoundError:
            raise
        except Exception as exc:
            raise Exception(f'Unable to read file: {file_path}') from exc

        if not content or not content.strip():
            raise ValueError(f'File is empty: {file_path}')

        try:
            list(csv.reader([content], delimiter=delimiter, quotechar=quotechar))
        except Exception as exc:
            raise Exception(f'Unable to parse CSV file: {file_path}') from exc

        return content.splitlines()

    lines1 = read_lines(file_path1)
    lines2 = read_lines(file_path2)

    differences = []
    line_number1 = 1
    line_number2 = 1

    for diff_line in ndiff(lines1, lines2):
        status = diff_line[:2]
        content = diff_line[2:]

        if status == '  ':
            differences.append({
                'Line Number': line_number1,
                'Status': ' ',
                'Content': content,
            })
            line_number1 += 1
            line_number2 += 1
        elif status == '- ':
            differences.append({
                'Line Number': line_number1,
                'Status': '-',
                'Content': content,
            })
            line_number1 += 1
        elif status == '+ ':
            differences.append({
                'Line Number': line_number2,
                'Status': '+',
                'Content': content,
            })
            line_number2 += 1

    return pd.DataFrame(
        differences,
        columns=['Line Number', 'Status', 'Content']
    )

