import numpy as np
import pandas as pd


def task_func(df1, df2, column1="feature1", column2="feature2"):
    if not isinstance(df1, pd.DataFrame) or not isinstance(df2, pd.DataFrame):
        raise TypeError("df1 and df2 must be pandas DataFrames")

    if column1 not in df1.columns:
        raise KeyError(f"Column {column1!r} is missing from df1")
    if column2 not in df2.columns:
        raise KeyError(f"Column {column2!r} is missing from df2")

    shared = [column for column in df1.columns if column in df2.columns]
    id_candidates = [
        column for column in shared
        if isinstance(column, str)
        and (
            column.lower() in {"id", "identifier"}
            or column.lower().endswith("_id")
        )
        and column not in {column1, column2}
    ]

    if len(id_candidates) == 1:
        id_column = id_candidates[0]
    elif len(id_candidates) > 1:
        raise ValueError("Could not uniquely identify the shared ID column")
    else:
        alternatives = [
            column for column in shared if column not in {column1, column2}
        ]
        if len(alternatives) != 1:
            raise ValueError("Could not identify a shared ID column")
        id_column = alternatives[0]

    if df1[id_column].duplicated().any() or df2[id_column].duplicated().any():
        raise ValueError("ID columns must contain unique values")

    if not pd.api.types.is_numeric_dtype(df1[column1]):
        raise TypeError(f"{column1!r} must be numeric")
    if not pd.api.types.is_numeric_dtype(df2[column2]):
        raise TypeError(f"{column2!r} must be numeric")

    merged = df1[[id_column, column1]].merge(
        df2[[id_column, column2]],
        on=id_column,
        how="inner",
    )

    if merged.empty:
        raise ValueError("The merged datasets contain no rows")

    values = merged[[column1, column2]].to_numpy(dtype=float)
    if not np.isfinite(values).all():
        raise ValueError("Feature columns must contain only finite values")
    if len(values) < 2:
        raise ValueError("At least two data points are required")

    labels = KMeans(n_clusters=2, n_init=10).fit_predict(values).astype(np.int32)

    _, ax = plt.subplots()
    ax.scatter(values[:, 0], values[:, 1], c=labels)
    ax.set_xlabel(column1)
    ax.set_ylabel(column2)

    return labels, ax

