import os
import glob
import shutil
import time

# Constants
FILE_EXTENSIONS = ['.txt', '.csv', '.xlsx', '.docx', '.pdf']


def task_func(my_path: str, days_old: int) -> str:
    if not isinstance(my_path, str) or not os.path.isdir(my_path):
        raise ValueError("my_path must be an existing directory")

    if isinstance(days_old, bool) or not isinstance(days_old, int) or days_old < 0:
        raise ValueError("days_old must be a non-negative integer")

    archive_path = os.path.join(my_path, "archive")
    os.makedirs(archive_path, exist_ok=True)

    threshold_seconds = days_old * 24 * 60 * 60
    current_time = time.time()

    for extension in FILE_EXTENSIONS:
        pattern = os.path.join(my_path, f"*{extension}")

        for file_path in glob.glob(pattern):
            if not os.path.isfile(file_path):
                continue

            if current_time - os.path.getmtime(file_path) > threshold_seconds:
                destination = os.path.join(
                    archive_path,
                    os.path.basename(file_path),
                )

                if os.path.exists(destination):
                    raise FileExistsError(
                        f"Archive destination already exists: {destination}"
                    )

                shutil.move(file_path, destination)

    return archive_path

import os
import hashlib
import json
from pathlib import Path


def task_func(directory: str) -> str:
    base_dir = Path(directory).expanduser().resolve()

    if not base_dir.exists():
        raise FileNotFoundError(f"Directory does not exist: {base_dir}")
    if not base_dir.is_dir():
        raise NotADirectoryError(f"Not a directory: {base_dir}")

    output_path = base_dir / "hashes.json"
    hashes = {}

    for file_path in base_dir.rglob("*"):
        if file_path.is_file() and file_path != output_path:
            digest = hashlib.sha256()

            with file_path.open("rb") as file:
                for chunk in iter(lambda: file.read(1024 * 1024), b""):
                    digest.update(chunk)

            relative_path = file_path.relative_to(base_dir).as_posix()
            hashes[relative_path] = digest.hexdigest()

    with output_path.open("w", encoding="utf-8") as file:
        json.dump(hashes, file, indent=2, sort_keys=True)
        file.write("\n")

    return str(output_path)

