        sampled.append(remaining.pop(selected_index))

    return sampled, dataframe

import zipfile
import os
import re
import shutil


def task_func(source_dir: str, target_dir: str, archive_name: str = 'archive.zip') -> str:
    if not os.path.exists(source_dir):
        raise FileNotFoundError(source_dir)
    if not os.path.isdir(source_dir):
        raise NotADirectoryError(source_dir)

    source_dir = os.path.abspath(source_dir)
    target_dir = os.path.abspath(target_dir)

    if not archive_name or os.path.isabs(archive_name):
        raise ValueError("archive_name must be a relative file path")

    archive_path = os.path.abspath(os.path.join(target_dir, archive_name))

    try:
        if os.path.commonpath((target_dir, archive_path)) != target_dir:
            raise ValueError("archive_name must remain inside target_dir")
    except ValueError as exc:
        raise ValueError("archive_name must remain inside target_dir") from exc

    if os.path.isdir(archive_path):
        raise IsADirectoryError(archive_path)

    os.makedirs(os.path.dirname(archive_path), exist_ok=True)

    archive_key = os.path.normcase(archive_path)
    files_to_archive = []

    for root, _, files in os.walk(source_dir):
        for filename in files:
            file_path = os.path.abspath(os.path.join(root, filename))

            if os.path.normcase(file_path) == archive_key:
                continue

            stem, _ = os.path.splitext(filename)
            if stem.endswith("_processed") and os.path.isfile(file_path):
                files_to_archive.append(file_path)

    with zipfile.ZipFile(
        archive_path,
        mode="w",
        compression=zipfile.ZIP_DEFLATED,
    ) as archive:
        for file_path in files_to_archive:
            archive.write(
                file_path,
                arcname=os.path.relpath(file_path, source_dir),
            )

    return archive_path

