import http.server
import json

SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}


class RequestHandler(http.server.BaseHTTPRequestHandler):
    def _send_response(self, status_code, body, content_type):
        encoded_body = body.encode('utf-8')
        self.send_response(status_code)
        self.send_header('Content-Type', content_type)
        self.send_header('Content-Length', str(len(encoded_body)))
        self.end_headers()
        self.wfile.write(encoded_body)

    def _send_error_message(self, message):
        self._send_response(400, message, 'text/plain; charset=utf-8')

    def do_POST(self):
        content_type = self.headers.get('Content-Type', '')
        media_type = content_type.split(';', 1)[0].strip().lower()

        if media_type != 'application/json':
            self._send_error_message(
                'Content-Type header is not application/json'
            )
            return

        try:
            content_length = int(self.headers.get('Content-Length', '0'))
            if content_length < 0:
                raise ValueError

            raw_body = self.rfile.read(content_length)
            if len(raw_body) != content_length:
                raise ValueError

            payload = json.loads(raw_body.decode('utf-8'))
        except (ValueError, UnicodeDecodeError, json.JSONDecodeError,
                OverflowError):
            self._send_error_message('Invalid JSON')
            return

        if not isinstance(payload, dict) or 'data' not in payload:
            self._send_error_message('No data key in request')
            return

        self._send_response(
            200,
            json.dumps(SUCCESS_RESPONSE),
            'application/json'
        )


def task_func():
    return RequestHandler

