        raise TypeError("sentences_dict must be a mapping")
    if word_keys is None or isinstance(word_keys, (str, bytes)):
        raise TypeError("word_keys must be an iterable of words")

    requested_words = []
    for word in word_keys:
        if word in WORDS and word not in requested_words:
            requested_words.append(word)

    sentences = list(sentences_dict.values())
    if any(not isinstance(sentence, str) for sentence in sentences):
        raise TypeError("All sentence values must be strings")

    tokens = []
    for sentence in sentences:
        current_token = []
        for character in sentence:
            if character.isalnum() or character == "_":
