def task_func(df, items=None, locations=None):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    if "Item" not in df.columns or "Location" not in df.columns:
        raise ValueError("df must contain 'Item' and 'Location' columns")

    default_items = ["Item A", "Item B", "Item C"]
    default_locations = ["Location A", "Location B", "Location C"]

    def deduplicate(values):
        result = []
        for value in values:
            if not any(value == existing for existing in result):
                result.append(value)
        return result

    selected_items = (
        default_items if items is None else deduplicate(list(items))
    )
    selected_locations = (
        default_locations
        if locations is None
        else deduplicate(list(locations))
    )

    data = df[["Item", "Location"]].dropna()
    counts = [
        [
            int(
                (
                    data["Item"].eq(item)
                    & data["Location"].eq(location)
                ).sum()
            )
            for location in selected_locations
        ]
        for item in selected_items
    ]

    _, ax = plt.subplots()

    location_positions = list(range(len(selected_locations)))
    item_count = len(selected_items)

    if item_count and selected_locations:
        width = 0.8 / item_count
        for item_index, (item, item_counts) in enumerate(
            zip(selected_items, counts)
        ):
            offsets = [
                position
                + (item_index - (item_count - 1) / 2) * width
                for position in location_positions
            ]
            ax.bar(offsets, item_counts, width=width, label=str(item))

    ax.set_xlabel("Location")
    ax.set_ylabel("Count")
    ax.set_title("Item Distribution by Location")
    ax.set_xticks(location_positions)
    ax.set_xticklabels([str(location) for location in selected_locations])

