import subprocess
import time
import json
import platform
import re

LOGFILE_PATH = "logfile.log"


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    system = platform.system()
    command = (
        ["wmic", "cpu", "get", "loadpercentage"]
        if system == "Windows"
        else ["top", "-bn1"]
    )

    measurements = []
    start_time = time.time()

    while True:
        try:
            output = subprocess.check_output(
                command,
                universal_newlines=True,
                stderr=subprocess.DEVNULL,
            )

            if isinstance(output, bytes):
                output = output.decode(errors="replace")

            cpu_usage = None

            if system == "Windows":
                for line in output.splitlines():
                    match = re.fullmatch(r"\s*(\d+(?:\.\d+)?)\s*", line)
                    if match:
                        cpu_usage = float(match.group(1))
                        break
            else:
                idle_match = re.search(
                    r"(?:%?cpu\(s\):|cpu\(s\):).*?"
                    r"(\d+(?:\.\d+)?)\s*%?\s*id\b",
                    output,
                    re.IGNORECASE | re.DOTALL,
                )
                if idle_match:
                    cpu_usage = 100.0 - float(idle_match.group(1))
                else:
                    numeric_match = re.fullmatch(
                        r"\s*(\d+(?:\.\d+)?)\s*", output
                    )
                    if numeric_match:
                        cpu_usage = float(numeric_match.group(1))

            if cpu_usage is not None:
                measurements.append(
                    {
                        "timestamp": time.time(),
                        "cpu_usage": max(0.0, min(100.0, cpu_usage)),
                    }
                )
        except (OSError, subprocess.SubprocessError):
            pass

        if time.time() - start_time >= duration:
            break

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as logfile:
            json.dump(measurements, logfile, indent=2)
    except IOError:
        return None

    return LOGFILE_PATH

