def task_func(date_str, tz_str):
    timezone = pytz.timezone(tz_str)
    parsed_date = parse(date_str)

    if parsed_date.tzinfo is None:
        current = timezone.localize(parsed_date)
    else:
        current = parsed_date.astimezone(timezone)

    current_year_start = timezone.localize(datetime(current.year, 1, 1))

    if current < current_year_start:
        next_new_year = current_year_start
    else:
        next_new_year = timezone.localize(datetime(current.year + 1, 1, 1))

    return int((next_new_year - current).total_seconds())

