def task_func(json_data: str, key_path: list):
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("JSON data must be a non-empty string")

    try:
        data = json.loads(json_data)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Invalid JSON data") from exc

    current = data
    for key in key_path:
        if not isinstance(current, dict) or key not in current:
            raise KeyError(key)
        current = current[key]

    values = []

    def collect(value):
        if isinstance(value, bool):
            return

        if isinstance(value, (int, float, np.integer, np.floating)):
            try:
                numeric_value = float(value)
            except (TypeError, ValueError, OverflowError) as exc:
                raise ValueError("Corrupted numerical data") from exc

            if not np.isfinite(numeric_value):
                raise ValueError("Corrupted numerical data")

            values.append(numeric_value)
            return

        if isinstance(value, dict):
            for nested_value in value.values():
                collect(nested_value)
        elif isinstance(value, (list, tuple)):
            for nested_value in value:
                collect(nested_value)

    collect(current)

    if not values:
        raise ValueError("No numeric data found")

    frame = pd.DataFrame({"value": values})
    figure, axis = plt.subplots()
    sns.boxplot(data=frame, x="value", ax=axis)

    axis.set_title("Boxplot of Numeric Data")
