import numpy as np
import base64
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding


def task_func(num, from_base, to_base, private_key, alphabet):
    if isinstance(from_base, bool) or not isinstance(from_base, (int, np.integer)):
        raise TypeError("from_base must be an integer")
    if isinstance(to_base, bool) or not isinstance(to_base, (int, np.integer)):
        raise TypeError("to_base must be an integer")
    if not 2 <= from_base <= 36 or not 2 <= to_base <= 36:
        raise ValueError("Bases must be between 2 and 36")

    if not isinstance(alphabet, str) or len(alphabet) != 64:
        raise ValueError("alphabet must contain exactly 64 unique characters")
    if len(set(alphabet)) != 64:
        raise ValueError("alphabet must contain exactly 64 unique characters")

    number_text = str(num)
    try:
        value = int(number_text, int(from_base))
    except (TypeError, ValueError) as exc:
        raise ValueError("num must be valid for from_base") from exc

    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if value == 0:
        converted = "0"
    else:
        sign = "-" if value < 0 else ""
        value = abs(value)
        converted_digits = []

        while value:
            value, remainder = divmod(value, int(to_base))
            converted_digits.append(digits[remainder])

        converted = sign + "".join(reversed(converted_digits))

    signature = private_key.sign(
        converted.encode("utf-8"),
        padding.PKCS1v15(),
        hashes.SHA256(),
    )

    standard_alphabet = (
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz"
        "0123456789+/"
    )
    encoded = base64.b64encode(signature).decode("ascii")
    translation = str.maketrans(standard_alphabet, alphabet)

    return encoded.translate(translation)

import re
import socket


def task_func(ip_addresses: list) -> dict:
    result = {}

    for ip_address in ip_addresses:
        if (
            not isinstance(ip_address, str)
            or not ip_address
            or re.search(r"\s", ip_address)
        ):
            continue

        valid = False
        for family in (socket.AF_INET, socket.AF_INET6):
            try:
                socket.inet_pton(family, ip_address)
                valid = True
                break
            except (OSError, ValueError):
                pass

        if not valid:
            continue

        try:
            result[ip_address] = socket.gethostbyaddr(ip_address)[0]
        except Exception:
            result[ip_address] = None

    return result

import numpy as np
from sympy import symbols, solve


def task_func(precision=2, seed=0):
    if isinstance(precision, bool) or not isinstance(precision, int) or precision < 0:
        raise ValueError("precision must be a non-negative integer")

    rng = np.random.RandomState(seed)
    a, b, c = rng.randint(-10, 11, size=3)

    while a == 0:
        a = rng.randint(-10, 11)

    x = symbols("x")
    solutions = solve(a * x**2 + b * x + c, x)

    if len(solutions) == 1:
        solutions *= 2

    return tuple(
        complex(
            round(complex(solution.evalf()).real, precision),
            round(complex(solution.evalf()).imag, precision),
        )
        for solution in solutions[:2]
    )

