import rsa
import os
import zipfile
from base64 import b64encode


def task_func(directory):
    if not os.path.exists(directory):
        raise FileNotFoundError(f"Directory does not exist: {directory}")
    if not os.path.isdir(directory):
        raise NotADirectoryError(f"Path is not a directory: {directory}")

    public_key, private_key = rsa.newkeys(2048)

    directory_path = os.path.abspath(directory)
    directory_name = os.path.basename(os.path.normpath(directory_path)) or "root"
    zip_filename = f"{directory_name}_encrypted.zip"
    zip_path = os.path.abspath(zip_filename)

    max_chunk_size = rsa.common.byte_size(public_key.n) - 11

    with zipfile.ZipFile(
        zip_path, "w", compression=zipfile.ZIP_DEFLATED
    ) as archive:
        for root, dirs, files in os.walk(directory_path, followlinks=False):
            dirs[:] = [
                name
                for name in dirs
                if not os.path.islink(os.path.join(root, name))
            ]

            for filename in files:
                file_path = os.path.join(root, filename)

                if (
                    os.path.islink(file_path)
                    or not os.path.isfile(file_path)
                    or os.path.abspath(file_path) == zip_path
                ):
                    continue

                with open(file_path, "rb") as source_file:
                    data = source_file.read()

                encrypted_data = b"".join(
                    rsa.encrypt(
                        data[index:index + max_chunk_size],
                        public_key,
                    )
                    for index in range(0, len(data), max_chunk_size)
                )

                archive_name = os.path.relpath(
                    file_path, directory_path
                ).replace(os.sep, "/")

                archive.writestr(archive_name, b64encode(encrypted_data))

    return public_key, zip_filename

