def task_func(df: pd.DataFrame, tuples: list, n_plots: int) -> (pd.DataFrame, list):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    if not isinstance(tuples, list):
        raise TypeError("tuples must be a list")

    if isinstance(n_plots, bool) or not isinstance(n_plots, int):
        raise TypeError("n_plots must be a non-negative integer")

    if n_plots < 0:
        raise ValueError("n_plots must be non-negative")

