    for item in tuples:
        if not isinstance(item, (tuple, list)) or len(item) != 2:
            raise ValueError("Each removal item must be a (column, value) pair")

        column, value = item

        if column not in result.columns:
            raise KeyError(f"Column not found: {column}")

        matches = result[column].eq(value).fillna(False).tolist()
        remove_mask = [
            current or match
            for current, match in zip(remove_mask, matches)
        ]

    result = result.loc[~pd.Series(remove_mask, index=result.index).to_numpy()]

    plot_columns = [column for column in COLUMNS if column in result.columns]
    axes = []

    for _ in range(n_plots):
        if len(plot_columns) < 2:
            break

        x_column, y_column = sample(plot_columns, 2)
