        df = pd.read_csv(csv_file)
    except pd.errors.EmptyDataError:
        return pd.DataFrame(columns=expected_columns), None

    required_columns = {"email", "list"}
    missing_columns = required_columns - set(df.columns)
    if missing_columns:
        raise ValueError(
            f"CSV file is missing required columns: {sorted(missing_columns)}"
        )

    if df.empty:
        for column in ["sum", "mean", "median"]:
            df[column] = pd.Series(dtype=float)
        return df, None

    def calculate_statistics(value):
        parsed = ast.literal_eval(value) if isinstance(value, str) else value
        values = np.asarray(parsed, dtype=float)

        if values.size == 0:
            return {"sum": 0.0, "mean": np.nan, "median": np.nan}

        return {
            "sum": float(np.sum(values)),
            "mean": float(np.mean(values)),
            "median": float(np.median(values)),
        }

    statistics = pd.DataFrame(
        df["list"].apply(calculate_statistics).tolist(),
        index=df.index,
    )
    df[["sum", "mean", "median"]] = statistics[
