from sklearn.feature_extraction.text import CountVectorizer


def task_func(df):
    title_column = next(
        (column for column in ("title", "article_title") if column in df.columns),
        None,
    )
    content_column = next(
        (
            column
            for column in ("content", "text", "article_text", "abstract", "body")
            if column in df.columns
        ),
        None,
    )

    if title_column is None:
        raise KeyError("DataFrame must contain a title column.")
    if content_column is None:
        raise KeyError("DataFrame must contain a content column.")

    pattern = re.compile(r"\b(?:how|what)\b", re.IGNORECASE)
    titles = df[title_column].fillna("").astype(str)

    matching_rows = df[titles.str.contains(pattern, regex=True, na=False)]

    if matching_rows.empty:
        return []

    documents = (
        matching_rows[content_column]
        .fillna("")
        .astype(str)
        .tolist()
    )

    try:
        matrix = CountVectorizer().fit_transform(documents)
    except ValueError:
        return [0] * len(documents)

    if len(documents) == 1:
        return [0]

    kmeans = KMeans(
        n_clusters=min(2, len(documents)),
        random_state=42,
        n_init=10,
    )
    return kmeans.fit_predict(matrix).tolist()

