import re
import json
import requests


def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        serialized = json.dumps(
            json.loads(response.text),
            ensure_ascii=False,
        )

        name_pattern = re.compile(r'"name"\s*:\s*"((?:\\.|[^"\\])*)"')

        depths = [0] * len(serialized)
        depth = 0
        in_string = False
        escaped = False

        for index, char in enumerate(serialized):
            depths[index] = depth

            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
            elif char == '"':
                in_string = True
            elif char == "[":
                depth += 1
            elif char == "]":
                depth = max(0, depth - 1)

        return [
            json.loads(f'"{match.group(1)}"')
            for match in name_pattern.finditer(serialized)
            if depths[match.start()] == 0
        ]
    except Exception:
        return "Invalid url input"

