import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def task_func(directory):
    if not os.path.isdir(BACKUP_DIR):
        return f"Backup directory {BACKUP_DIR} does not exist. Cannot rollback update."

    try:
        if not isinstance(directory, str) or not directory:
            return f"Failed to rollback update for {directory}: invalid directory path."

        target_path = os.path.abspath(directory)
        directory_name = os.path.basename(os.path.normpath(directory))

        if directory_name in ("", "."):
            return f"Failed to rollback update for {directory}: invalid directory path."

        backup_path = os.path.abspath(os.path.join(BACKUP_DIR, directory_name))

        if not os.path.isdir(backup_path):
            return f"Backup for directory {directory} does not exist."

        if target_path == backup_path:
            return "Cannot rollback because the backup and target directories are the same."

        if os.path.commonpath((target_path, backup_path)) == backup_path:
            return "Cannot rollback because the target directory is inside the backup directory."

        if os.path.exists(directory):
            if os.path.isdir(directory) and not os.path.islink(directory):
                shutil.rmtree(directory)
            else:
                os.remove(directory)

        parent = os.path.dirname(target_path)
        os.makedirs(parent, exist_ok=True)
        shutil.copytree(backup_path, target_path)

        return directory

    except (OSError, ValueError, TypeError) as error:
        return f"Failed to rollback update for {directory}: {error}"

