from typing import List, Union
import numpy as np
import scipy.fft


def task_func(data: List[Union[int, str]], repetitions: int = 1) -> dict:
    if not data or repetitions <= 0:
        return {"mode": np.array([]), "count": np.array([])}

    repeated = data * repetitions

    frequencies = {}
    for value in repeated:
        frequencies[value] = frequencies.get(value, 0) + 1

    maximum_count = max(frequencies.values())
    modes = [
        value for value, count in frequencies.items()
        if count == maximum_count
    ]

    try:
        modes.sort()
    except TypeError:
        modes.sort(key=lambda value: (type(value).__name__, str(value)))

    if all(isinstance(value, (int, np.integer)) for value in repeated):
        scipy.fft.fft(np.asarray(repeated))

    return {
        "mode": np.asarray(modes),
        "count": np.full(len(modes), maximum_count, dtype=int),
    }

import numpy as np
import pandas as pd
from numbers import Real


def task_func(
    products,
    n_samples=100,
    sales_lower=50,
    sales_upper=200,
    profit_margin_min=0.1,
    profit_margin_max=0.5,
    random_seed=42,
):
    if not isinstance(products, list) or not all(
        isinstance(product, str) for product in products
    ):
        raise TypeError("products must be a list of strings")

    if (
        isinstance(n_samples, bool)
        or not isinstance(n_samples, (int, np.integer))
        or n_samples <= 0
    ):
        raise ValueError("n_samples must be a positive integer")

    bounds = (
        sales_lower,
        sales_upper,
        profit_margin_min,
        profit_margin_max,
    )
    if any(isinstance(value, bool) or not isinstance(value, Real) for value in bounds):
        raise TypeError("Sales bounds and profit margins must be numeric")

    if sales_lower > sales_upper:
        raise ValueError("sales_lower cannot be greater than sales_upper")

    columns = ["product", "total_sales", "total_profit"]

    if not products:
        return pd.DataFrame(columns=columns)

    rng = np.random.default_rng(random_seed)

    sampled_products = rng.choice(products, size=n_samples)
    sales = rng.uniform(sales_lower, sales_upper, size=n_samples)
    margins = rng.uniform(profit_margin_min, profit_margin_max, size=n_samples)
    profits = sales * margins

    data = pd.DataFrame(
        {
            "product": sampled_products,
            "sales": sales,
            "profit": profits,
        }
    )

    report = (
        data.groupby("product", as_index=False)[["sales", "profit"]]
        .sum()
        .rename(
            columns={
                "sales": "total_sales",
                "profit": "total_profit",
            }
        )
    )

    report = (
        report.set_index("product")
        .reindex(dict.fromkeys(products), fill_value=0)
        .reset_index()
    )

    return (
        report.sort_values(
            by=["total_profit", "product"],
            ascending=[False, True],
        )
        .reset_index(drop=True)[columns]
    )

