def task_func(xml_content, output_csv_path):
    root = ET.fromstring(xml_content)

    headers = []
    for row in root:
        for field in row:
            if field.tag not in headers:
                headers.append(field.tag)

    with open(output_csv_path, "w", encoding="utf-8", newline="") as csv_file:
        if not len(root):
            return None

        writer = csv.DictWriter(csv_file, fieldnames=headers)
        writer.writeheader()

        for row in root:
            values = {}
            for field in row:
                values.setdefault(field.tag, field.text or "")
            writer.writerow(values)

    return None

