import numpy as np
import pandas as pd

# Constants
COLUMNS = ['Column1', 'Column2', 'Column3', 'Column4', 'Column5']


def task_func(length, min_value=0, max_value=100):
    """Generate random data and return its empirical CDF by column."""
    if isinstance(length, bool) or not isinstance(length, (int, np.integer)):
        raise TypeError("length must be an integer")
    if length < 0:
        raise ValueError("length must be non-negative")

    if isinstance(min_value, bool) or not isinstance(min_value, (int, float, np.number)):
        raise TypeError("min_value must be numeric")
    if isinstance(max_value, bool) or not isinstance(max_value, (int, float, np.number)):
        raise TypeError("max_value must be numeric")
    if not np.isfinite(min_value) or not np.isfinite(max_value):
        raise ValueError("range values must be finite")
    if min_value > max_value:
        raise ValueError("min_value must not exceed max_value")

    if length == 0:
        return pd.DataFrame(columns=COLUMNS, dtype=float)

    data = np.random.uniform(
        low=min_value,
        high=max_value,
        size=(length, len(COLUMNS)),
    )

    cdf = np.empty_like(data, dtype=float)
    for column_index in range(data.shape[1]):
        sorted_values = np.sort(data[:, column_index])
        cdf[:, column_index] = (
            np.searchsorted(
                sorted_values,
                data[:, column_index],
                side="right",
            )
            / length
        )

    return pd.DataFrame(cdf, columns=COLUMNS)

