from scipy import stats
import matplotlib.pyplot as plt
import numpy as np


def task_func(data_dict, data_keys):
    if len(data_keys) != 2:
        raise ValueError("data_keys must contain exactly two keys")

    first_key, second_key = data_keys

    try:
        x = np.asarray(data_dict[first_key], dtype=float)
        y = np.asarray(data_dict[second_key], dtype=float)
    except (TypeError, ValueError) as exc:
        raise ValueError("Data series must contain numeric values") from exc

    if x.ndim != 1 or y.ndim != 1:
        raise ValueError("Data series must be one-dimensional")

    if len(x) != len(y):
        raise ValueError("Data series must have equal lengths")

    if len(x) < 2:
        raise ValueError("Data series must contain at least two observations")

    if not np.all(np.isfinite(x)) or not np.all(np.isfinite(y)):
        raise ValueError("Data series must contain only finite values")

    if np.all(x == x[0]) or np.all(y == y[0]):
        raise ValueError("Pearson correlation is undefined for constant data")

    correlation = float(stats.pearsonr(x, y)[0])

    _, ax = plt.subplots()
    ax.scatter(x, y)
    ax.set_xlabel(str(first_key))
    ax.set_ylabel(str(second_key))

    return correlation, ax

