import pandas as pd

def task_func(pattern: str, directory: str, output_csv: str) -> pd.DataFrame:
    regex = re.compile(pattern)

    if not os.path.isdir(directory):
        if os.path.exists(directory):
            raise NotADirectoryError(f"Not a directory: {directory}")
        raise FileNotFoundError(f"Directory not found: {directory}")

    matched_paths = []

    for root, _, filenames in os.walk(directory, onerror=lambda error: (_ for _ in ()).throw(error)):
        for filename in filenames:
            if regex.search(filename):
                matched_paths.append(os.path.join(root, filename))

    result = pd.DataFrame({"File Path": matched_paths})
    result.to_csv(output_csv, index=False)

    return result

