import pandas as pd
import json
import os
import math


def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("JSON data must be a non-empty string")

    try:
        data = json.loads(json_data)
    except (json.JSONDecodeError, TypeError, RecursionError) as exc:
        raise ValueError("Malformed JSON data") from exc

    if not isinstance(data, dict) or not data:
        raise ValueError("JSON data must be a non-empty object")

    rows = []

    for country, population in data.items():
        if not isinstance(country, str):
            raise ValueError("Country names must be strings")

        if isinstance(population, bool) or not isinstance(population, (int, float)):
            raise ValueError("Populations must be finite, non-negative numbers")

        if isinstance(population, float) and not math.isfinite(population):
            raise ValueError("Populations must be finite, non-negative numbers")

        if population < 0:
            raise ValueError("Populations must be finite, non-negative numbers")

        rows.append(
            {
                "Country": country,
                "Population": math.floor(population)
                if isinstance(population, float)
                else population,
            }
        )

    dataframe = pd.DataFrame(rows, columns=["Country", "Population"])

    try:
        output_path = os.path.join(output_dir, file_name)
        dataframe.to_csv(output_path, index=False)
    except (OSError, TypeError, ValueError) as exc:
        raise IOError(f"Unable to write CSV file") from exc

    return output_path, dataframe

