def task_func(excel_file_path, file_name, column_name):
    file_path = os.path.join(excel_file_path, file_name)

    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"Excel file not found: {file_path}")

    data = pd.read_excel(file_path)

    if column_name not in data.columns:
        raise ValueError(f"Column not found: {column_name}")

    values = data[column_name].dropna().to_numpy()

    if len(values) == 0:
        return {
            "mean": np.nan,
            "median": np.nan,
            "std": np.nan,
        }

    return {
        "mean": np.mean(values),
        "median": np.median(values),
        "std": np.std(values),
    }

import heapq
from sklearn.preprocessing import StandardScaler


def task_func(df, col1, col2, N=10):
    if col1 not in df.columns or col2 not in df.columns:
        raise ValueError("Specified columns are not in the provided DataFrame.")

    if N <= 0 or df.empty:
        return []

    standardized = StandardScaler().fit_transform(df[[col1, col2]])
    differences = abs(standardized[:, 0] - standardized[:, 1])

    return heapq.nlargest(
        min(N, len(differences)),
        range(len(differences)),
        key=lambda index: differences[index],
    )

