import os
import subprocess
import tempfile

logger = logging.getLogger(__name__)


def task_func(filepath):
    source_path = os.fspath(filepath)

    if not os.path.isfile(source_path):
        raise FileNotFoundError(f"Source file not found: {source_path}")

    try:
        with tempfile.TemporaryDirectory() as temp_dir:
            output_path = os.path.join(temp_dir, "program")

            result = subprocess.run(
                ["g++", source_path, "-o", output_path],
                check=True,
                capture_output=True,
                text=True,
            )

            if result.stdout:
                logger.info("Compiler output:\n%s", result.stdout)
            if result.stderr:
                logger.warning("Compiler warnings:\n%s", result.stderr)

            logger.info("Compilation successful: %s", source_path)

    except subprocess.CalledProcessError as error:
        if error.stdout:
            logger.error("Compiler output:\n%s", error.stdout)
        if error.stderr:
            logger.error("Compilation failed:\n%s", error.stderr)
        raise
    except FileNotFoundError:
        logger.error("Compiler not found or source file is unavailable.")
        raise

