    assignments = [
        {
            "Task Name": str(task).replace(" ", "_"),
            "Assigned To": rng.choice(employees),
            "Due Date": due_date,
        }
        for task in selected_tasks
    ]

    return pd.DataFrame(assignments, columns=columns)

