import heapq
from scipy import stats


def task_func(df, col1, col2, N=10):
    if col1 not in df.columns or col2 not in df.columns:
        raise ValueError("Specified columns are not in the DataFrame.")

    if N <= 1:
        raise ValueError("N must be greater than 1.")

    differences = (df[col1] - df[col2]).abs()
    count = min(N, len(df))
    selected_indices = heapq.nlargest(
        count,
        range(len(df)),
        key=differences.iloc.__getitem__,
    )

    return float(
        stats.ttest_ind(
            df[col1].iloc[selected_indices],
            df[col2].iloc[selected_indices],
        ).pvalue
    )

import random
import string


def task_func(length: int, predicates: list, seed: int = None):
    if length < 0:
        raise ValueError("length must be non-negative")

    predicate_checks = {
        "isalpha": str.isalpha,
        "isdigit": str.isdigit,
        "isalnum": str.isalnum,
        "islower": str.islower,
        "isupper": str.isupper,
        "isspace": str.isspace,
        "isprintable": str.isprintable,
    }

    unique_predicates = list(dict.fromkeys(predicates))

    for predicate in unique_predicates:
        if predicate not in predicate_checks:
            raise KeyError(predicate)

    rng = random.Random(seed)
    alphabet = string.ascii_letters + string.digits + string.punctuation
    text = "".join(rng.choices(alphabet, k=length))

    characteristics = {
        predicate: predicate_checks[predicate](text)
        for predicate in unique_predicates
    }

    return text, characteristics

