from collections import Counter
import os
import json


def task_func(filename, directory):
    if not os.path.isdir(directory):
        raise NotADirectoryError(f"Not a directory: {directory}")

    output_path = os.path.realpath(os.path.abspath(filename))
    word_counts = Counter()

    with os.scandir(directory) as entries:
        for entry in entries:
            if not entry.is_file():
                continue
            if not entry.name.lower().endswith(".txt"):
                continue
            if os.path.realpath(entry.path) == output_path:
                continue

            with open(entry.path, "r", encoding="utf-8") as file:
                word_counts[entry.name] = len(file.read().split())

    with open(filename, "w", encoding="utf-8") as output_file:
        json.dump(dict(word_counts), output_file, ensure_ascii=False, indent=2)

    return sum(word_counts.values())

import subprocess
import os
import glob
import time


def task_func(test_dir):
    execution_times = {}
    script_paths = sorted(
        glob.glob(os.path.abspath(os.path.join(test_dir, "*.py")))
    )

    for script_path in script_paths:
        script_name = os.path.basename(script_path)
        start_time = time.perf_counter()

        try:
            subprocess.run(
                ["python", script_path],
                check=False,
                cwd=os.path.abspath(test_dir),
            )
        except OSError:
            pass
        finally:
            execution_times[script_name] = time.perf_counter() - start_time

    return execution_times

