import random
import math


def task_func(range_start=1, range_end=100, pairs_count=10, random_seed=None):
    rng = random.Random(random_seed)

    def generate_pairs():
        for _ in range(pairs_count):
            num1 = rng.randint(range_start, range_end)
            num2 = rng.randint(range_start, range_end)
            yield (num1, num2, math.sqrt(abs(num1 - num2)))

    return generate_pairs()

import numpy as np
import pandas as pd
from sklearn.linear_model import LinearRegression


def task_func(df, target_column, target_values=None):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    if not isinstance(target_column, str):
        raise ValueError("target_column must be a string")

    if target_column not in df.columns:
        raise ValueError("target_column must exist in df")

    result = df.copy()

    if target_values is not None:
        if isinstance(target_values, (str, bytes)) or not pd.api.types.is_list_like(
            target_values
        ):
            raise ValueError("target_values must be array-like")

        values = list(target_values)

        for column in result.columns:
            if column != target_column:
                result[column] = result[column].where(
                    result[column].isin(values), 0
                )

    X = result.drop(columns=[target_column])
    y = result[target_column]

    model = LinearRegression()
    model.fit(X, y)

    return model

