def task_func(
    dic={'Lon': (-180, 180), 'Lat': (-90, 90)},
    cities=['New York', 'London', 'Beijing', 'Tokyo', 'Sydney']
):
    if 'Lon' not in dic or 'Lat' not in dic:
        raise ValueError("'Lon' and 'Lat' keys are required")

    if not isinstance(dic['Lon'], tuple) or not isinstance(dic['Lat'], tuple):
        raise ValueError("'Lon' and 'Lat' values must be tuples")

    if len(dic['Lon']) != 2 or len(dic['Lat']) != 2:
        raise ValueError("Coordinate ranges must contain exactly two values")

    try:
        lon_min, lon_max = map(float, dic['Lon'])
        lat_min, lat_max = map(float, dic['Lat'])
    except (TypeError, ValueError):
        raise ValueError("Coordinate range values must be numeric")

    if lon_min > lon_max or lat_min > lat_max:
