import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt

# Constants
HEADERS = {
    'accept': 'application/json'
}


def task_func(url, parameters):
    """Retrieve API data, create a DataFrame, and display a correlation heatmap."""
    if not isinstance(url, str) or not url.strip():
        raise Exception("Invalid URL.")

    if parameters is not None and not isinstance(parameters, (dict, list, tuple)):
        raise Exception("Invalid parameters.")

    try:
        response = requests.get(
            url,
            params=parameters,
            headers=HEADERS,
            timeout=10
        )
        response.raise_for_status()
    except Exception as exc:
        raise Exception("URL cannot be accessed.") from exc

    try:
        try:
            payload = response.json()
        except Exception:
            payload = json.loads(response.text)
    except Exception as exc:
        raise Exception("Invalid JSON data.") from exc

    if payload is None or payload == [] or payload == {}:
        raise Exception("Empty data.")

    if isinstance(payload, dict):
        for key in ("data", "results", "items"):
            if key in payload:
                payload = payload[key]
                break

    if isinstance(payload, list):
        if not payload or not all(isinstance(row, dict) for row in payload):
            raise Exception("Invalid data.")
        records = payload
    elif isinstance(payload, dict):
        if any(isinstance(value, (dict, list)) for value in payload.values()):
            raise Exception("Invalid data.")
        records = [payload]
    else:
        raise Exception("Invalid data.")

    try:
        dataframe = pd.DataFrame(records)
    except Exception as exc:
        raise Exception("Unable to create DataFrame.") from exc

    if dataframe.empty:
        raise Exception("Empty data.")

    numeric_columns = dataframe.select_dtypes(include="number").columns
    if len(numeric_columns) < 2:
        raise Exception("At least two numerical columns are required.")

    correlation = dataframe[numeric_columns].corr()

    if correlation.isna().all().all():
        raise Exception("Numerical data is insufficient for correlation.")

    _, axes = plt.subplots()
    heatmap_axes = sns.heatmap(
        correlation,
        annot=True,
        cmap="coolwarm",
        center=0,
        ax=axes
    )
    heatmap_axes.set_title("Correlation Heatmap")
    plt.show()

    return dataframe, heatmap_axes

import random
import re


def task_func(text, seed=None):
    rng = random.Random(seed)

    def scramble(match):
        word = match.group(0)
        if len(word) <= 3:
            return word

        middle = list(word[1:-1])
        rng.shuffle(middle)
        return word[0] + "".join(middle) + word[-1]

    return re.sub(r"\b\w+\b", scramble, text)

import subprocess
import os
import time
import glob


def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    success_message = "File generated successfully within the specified duration."
    failure_message = "File not generated within the specified duration."

    if (
        not isinstance(r_script_path, str)
        or not r_script_path
        or not os.path.isfile(r_script_path)
        or not isinstance(output_path, str)
        or not output_path
        or not isinstance(duration, int)
        or isinstance(duration, bool)
        or duration < 0
    ):
        return False, failure_message

    def output_generated() -> bool:
        if glob.has_magic(output_path):
            return any(os.path.isfile(path) for path in glob.glob(output_path))
        return os.path.isfile(output_path)

    def cleanup(process) -> None:
        try:
            if process.poll() is None:
                process.terminate()
                try:
                    process.wait(timeout=1)
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.wait()
        except (OSError, subprocess.SubprocessError):
            pass

    start_time = time.monotonic()

    try:
        process = subprocess.Popen(["Rscript", r_script_path])
    except (OSError, ValueError, subprocess.SubprocessError):
        return False, failure_message

    try:
        while True:
            if output_generated():
                return True, success_message

            elapsed = time.monotonic() - start_time
            if elapsed >= duration:
                break

            time.sleep(min(0.05, duration - elapsed))

        if output_generated():
            return True, success_message

        return False, failure_message
    except (OSError, subprocess.SubprocessError):
        return False, failure_message
    finally:
        cleanup(process)

import numpy as np
import matplotlib.pyplot as plt


def task_func(P, T):
    if not isinstance(P, (np.ndarray, np.matrix)):
        raise TypeError("P must be a NumPy array or matrix.")
    if not isinstance(T, (np.ndarray, np.matrix)):
        raise TypeError("T must be a NumPy array or matrix.")

    P = np.asarray(P)
    T = np.asarray(T)

    if P.ndim != 2:
        raise ValueError("P must be a 2D matrix.")
    if T.ndim != 3:
        raise ValueError("T must be a 3D tensor.")
    if T.shape[2] != 3:
        raise ValueError("The last dimension of T must have size 3.")
    if P.shape[1] != T.shape[0]:
        raise ValueError(
            "The second dimension of P must match the first dimension of T."
        )
    if np.iscomplexobj(P) or np.iscomplexobj(T):
        raise TypeError("Complex-valued inputs cannot be visualized in 3D.")

    result = np.einsum("nm,mkq->nq", P, T)

    fig = plt.figure()
    ax = fig.add_subplot(111, projection="3d")
    ax.scatter(result[:, 0], result[:, 1], result[:, 2])

    ax.set_xlabel("X")
    ax.set_ylabel("Y")
    ax.set_zlabel("Z")
    ax.set_title("Matrix–Tensor Einstein Summation Product")

    return result, ax

