from collections import Counter


def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    if not os.path.isdir(directory):
        raise OSError(f"Directory does not exist: {directory}")

    extensions = list(dict.fromkeys(extensions))
    counts = Counter({extension: 0 for extension in extensions}) if keep_zero else Counter()

    def raise_error(error):
        raise error

    for root, _, files in os.walk(directory, onerror=raise_error):
        for filename in files:
            filepath = os.path.join(root, filename)

            if not os.path.isfile(filepath):
                continue

            for extension in extensions:
                if filename.endswith(extension):
                    counts[extension] += 1

    return counts

import math
import numpy as np
from datetime import datetime, timedelta
import pandas as pd


def task_func(
    start_time,
    end_time,
    step,
    columns=["Timestamp", "Sensor1", "Sensor2", "Sensor3", "SensorStatus"],
    sensor_statuses=["OK", "MAINTENANCE_REQUIRED", "ERROR"],
    random_seed=42,
):
    if not isinstance(start_time, datetime) or not isinstance(end_time, datetime):
        raise TypeError("start_time and end_time must be datetime objects")

    if isinstance(step, pd.Timedelta):
        step = step.to_pytimedelta()
    elif isinstance(step, np.timedelta64):
        step = pd.Timedelta(step).to_pytimedelta()

    if not isinstance(step, timedelta):
        raise TypeError("step must be a datetime.timedelta")
    if step <= timedelta(0):
        raise ValueError("step must be positive")
    if start_time > end_time:
        raise ValueError("start_time must not be later than end_time")
    if len(columns) != 5:
        raise ValueError("columns must contain exactly five names")
    if len(set(columns)) != len(columns):
        raise ValueError("columns must not contain duplicates")
    if len(sensor_statuses) == 0:
        raise ValueError("sensor_statuses must not be empty")

    timestamps = []
    current = start_time

    while current <= end_time:
        timestamps.append(current)
        try:
            current += step
        except OverflowError:
            break

    rng = np.random.default_rng(random_seed)
    seconds = np.asarray(
        [timestamp.timestamp() for timestamp in timestamps],
        dtype=float,
    )
    noise = rng.normal(0.0, 0.01, size=(len(timestamps), 3))

    with np.errstate(over="ignore", invalid="ignore"):
        sensor1 = np.sin(seconds) + noise[:, 0]
        sensor2 = np.cos(seconds) + noise[:, 1]
        sensor3 = np.tan(seconds) + noise[:, 2]

    statuses = rng.choice(sensor_statuses, size=len(timestamps))

    return pd.DataFrame(
        {
            columns[0]: timestamps,
            columns[1]: sensor1,
            columns[2]: sensor2,
            columns[3]: sensor3,
            columns[4]: statuses,
        },
        columns=columns,
    )

