def task_func(radius, num_points):
    if isinstance(radius, bool) or not isinstance(radius, (int, float, np.number)):
        raise ValueError("radius must be a non-negative number")
    if not math.isfinite(float(radius)) or radius < 0:
        raise ValueError("radius must be a non-negative number")

    if isinstance(num_points, bool) or not isinstance(num_points, (int, np.integer)):
        raise ValueError("num_points must be a non-negative integer")
    if num_points < 0:
        raise ValueError("num_points must be a non-negative integer")

    points = []
