import os
import requests
from zipfile import ZipFile, BadZipFile
import tempfile


def task_func(url, download_path="mnt/data/downloads/"):
    temp_path = None

    try:
        os.makedirs(download_path, exist_ok=True)

        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()

        content_type = response.headers.get("Content-Type", "")
        media_type = content_type.split(";", 1)[0].strip().lower()

        if media_type != "application/zip":
            return "Error: The URL does not point to a ZIP file."

        with tempfile.NamedTemporaryFile(
            dir=download_path,
            suffix=".zip",
            delete=False,
        ) as temp_file:
            temp_path = temp_file.name
            try:
                for chunk in response.iter_content(chunk_size=8192):
                    if chunk:
                        temp_file.write(chunk)
            except (requests.exceptions.RequestException, OSError):
                return "Error: Unable to download the file from the provided URL."

        try:
            with ZipFile(temp_path, "r") as zip_file:
                zip_file.extractall(download_path)
        except (BadZipFile, OSError, EOFError, RuntimeError):
            return "Error: The downloaded file is not a valid ZIP file."

        return str(download_path)

    except requests.exceptions.RequestException:
        return "Error: Unable to download the file from the provided URL."
    except Exception as exc:
        return f"Error: {exc}"
    finally:
        if temp_path and os.path.exists(temp_path):
            try:
                os.remove(temp_path)
            except OSError:
                pass

