import os
import shutil


def task_func(path, delimiter="/"):
    if not isinstance(path, str) or not path or not path.strip():
        raise ValueError("path must be a non-empty string")

    if not isinstance(delimiter, str) or not delimiter:
        raise ValueError("delimiter must be a non-empty string")

    if path == delimiter and delimiter == os.sep:
        components = [os.sep]
    else:
        is_absolute = path.startswith(delimiter)
        raw_components = path.split(delimiter)

        if is_absolute:
            raw_components = raw_components[1:]

        if any(component in ("", ".", "..") for component in raw_components):
            raise ValueError("path contains invalid components")

        components = ([os.sep] if is_absolute else []) + raw_components

    result = []
    current_path = ""

    for component in components:
        if component == os.sep:
            current_path = os.sep
        else:
            current_path = (
                os.path.join(current_path, component)
                if current_path
                else component
            )

        if not os.path.exists(current_path):
            raise FileNotFoundError(current_path)

        if not os.path.isdir(current_path):
            raise ValueError(f"not a directory: {current_path}")

        usage = shutil.disk_usage(current_path)
        result.append(
            (
                component,
                {
                    "total": usage.total,
                    "used": usage.used,
                    "free": usage.free,
                },
            )
        )

    return result

