        timestamps = pd.date_range(
            start=start,
            end=end,
            freq=step,
            inclusive="both",
        )
    except Exception as exc:
        raise ValueError("step must be a valid positive time interval") from exc

    if len(timestamps) == 0:
        timestamps = pd.DatetimeIndex([start])

    positions = np.arange(len(timestamps), dtype=float)
    values = float(amplitude) * np.sin(
        2 * np.pi * positions / float(period)
    )

    data = pd.DataFrame(
        {
            "Timestamp": timestamps,
            "Value": values,
        }
    )

    ax = data.plot(
        x="Timestamp",
        y="Value",
        title="Time Series with Seasonality",
        legend=False,
    )
    ax.set_xlabel("Timestamp")
    ax.set_ylabel("Value")

    return ax

