from random import randint


def task_func(dict1):
    result = defaultdict(list)
    salary_keys = {"salary", "salary_amount", "pay"}

    if not isinstance(dict1, dict):
        return {}

    def extract_salary(employee):
        if isinstance(employee, dict):
            for key, value in employee.items():
                if str(key).lower() in salary_keys:
                    return value
            return None

        if isinstance(employee, (list, tuple)):
            return employee[-1] if employee else None

        return employee

    for department, employees in dict1.items():
        if not isinstance(department, str) or not department.startswith("EMP$$"):
            continue

        if isinstance(employees, dict):
            if any(str(key).lower() in salary_keys for key in employees):
                salary = extract_salary(employees)
                if salary is not None:
                    result[department].append(salary)
            else:
                for employee in employees.values():
                    salary = extract_salary(employee)
                    if salary is not None:
                        result[department].append(salary)
        elif isinstance(employees, (list, tuple)):
            for employee in employees:
                salary = extract_salary(employee)
                if salary is not None:
                    result[department].append(salary)
        else:
            result[department].append(employees)

    return dict(result)

