        else:
            timestamp = timestamp.tz_convert(target_timezone)

        return timestamp.hour

    data = pd.DataFrame(articles)
    data["publication_hour"] = data["published_time"].apply(
        get_publication_hour
    )

    result = data.groupby("category")["publication_hour"].agg(
        count="count",
        mean="mean",
        min="min",
        max="max",
    )

    result.index.name = "category"
    return result

