def task_func(file_name):
    with open(file_name, newline="", encoding="utf-8") as file:
        reader = csv.DictReader(file)

        if not reader.fieldnames:
            return {}

        counters = {
            column: collections.Counter()
            for column in reader.fieldnames
        }

        for row in reader:
            for column in reader.fieldnames:
                counters[column][row.get(column)] += 1

        result = {}
        for column, counter in counters.items():
            if not counter:
                result[column] = None
                continue

            max_count = max(counter.values())
            candidates = [
                value for value, count in counter.items()
                if count == max_count
            ]
            result[column] = sorted(
                candidates,
                key=lambda value: "" if value is None else str(value)
            )[0]

        return result

