import subprocess
import psutil
import time
import os


def task_func(script_path: str, timeout=10) -> dict:
    if not script_path:
        raise ValueError("script_path must not be empty")
    if not os.path.exists(script_path):
        raise FileNotFoundError(script_path)
    if not os.path.isfile(script_path):
        raise IsADirectoryError(script_path)
    if timeout <= 0:
        raise ValueError("timeout must be greater than zero")

    accumulated_cpu = 0.0
    accumulated_memory = 0
    process = subprocess.Popen(["bash", script_path])
    monitored_process = psutil.Process(process.pid)
    deadline = time.monotonic() + timeout

    def stop_process() -> None:
        if process.poll() is not None:
            return
        try:
            process.terminate()
            process.wait(timeout=1)
        except (subprocess.TimeoutExpired, OSError):
            try:
                process.kill()
            except OSError:
                pass
            try:
                process.wait()
            except OSError:
                pass

    try:
        try:
            monitored_process.cpu_percent(None)
        except (
            psutil.NoSuchProcess,
            psutil.ZombieProcess,
            psutil.AccessDenied,
        ):
            return {
                "CPU Usage": accumulated_cpu,
                "Memory Usage": accumulated_memory,
            }

        while process.poll() is None:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                stop_process()
                break

            time.sleep(min(0.1, remaining))

            try:
                if monitored_process.status() == psutil.STATUS_ZOMBIE:
                    break

                accumulated_cpu += monitored_process.cpu_percent(None)
                accumulated_memory += monitored_process.memory_info().rss
            except (
                psutil.NoSuchProcess,
                psutil.ZombieProcess,
                psutil.AccessDenied,
            ):
                break
    finally:
        if process.poll() is None:
            stop_process()

    return {
        "CPU Usage": accumulated_cpu,
        "Memory Usage": accumulated_memory,
    }

