        if (
            os.path.isfile(path)
            and os.path.abspath(path) != os.path.abspath(zip_path)
        ):
            files.append(path)

    if not files:
        return None

    with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as archive:
        for file_path in files:
            archive.write(file_path, arcname=os.path.basename(file_path))

    return zip_path

import json
import re
from collections import Counter

# Constants
REPLACE_NONE = "None"


def task_func(json_str):
    email_pattern = re.compile(
        r"[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@"
        r"[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+",
        re.IGNORECASE,
    )

    def process(value):
        if value is None:
            return None

        if isinstance(value, str):
            return email_pattern.sub(REPLACE_NONE, value)

        if isinstance(value, list):
            return [process(item) for item in value if item is not None]

        if isinstance(value, dict):
            return {
                key: process(item)
                for key, item in value.items()
                if item is not None
            }

        return value

    def count_values(value, counts):
        if isinstance(value, dict):
            for item in value.values():
                count_values(item, counts)
        elif isinstance(value, list):
            for item in value:
                count_values(item, counts)
        elif value is not None:
            counts[value] += 1

    data = process(json.loads(json_str))
    value_counts = Counter()
    count_values(data, value_counts)

    return {
        "data": data,
        "value_counts": value_counts,
    }

