import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    if not isinstance(data, pd.DataFrame):
        raise TypeError("data must be a pandas DataFrame")

    if not isinstance(mapping, dict):
        raise TypeError("mapping must be a dictionary")

    if any(
        not isinstance(key, str)
        or not key
        or not isinstance(value, str)
        for key, value in mapping.items()
    ):
        raise TypeError(
            "mapping must contain non-empty string keys and string values"
        )

    result = data.copy()

    if not mapping:
        return result

    acronyms = sorted(mapping, key=len, reverse=True)
    pattern = re.compile(
        r"(?<!\w)(?:"
        + "|".join(re.escape(acronym) for acronym in acronyms)
        + r")(?!\w)"
    )

    def replace_acronyms(value):
        if isinstance(value, str):
            return pattern.sub(
                lambda match: mapping[match.group(0)],
                value,
            )
        return value

    return result.applymap(replace_acronyms)

