def task_func(user, API_URL='https://api.github.com/users/'):
    endpoint = f"{API_URL.rstrip('/')}/{user}/repos"
    repositories = []
    page = 1

    while True:
        response = requests.get(
            endpoint,
            params={"page": page, "per_page": 100},
        )

        if hasattr(response, "raise_for_status"):
            response.raise_for_status()

        payload = response.json()

        if not isinstance(payload, list):
            break

        for repository in payload:
            if not isinstance(repository, dict):
                continue

            name = repository.get("name")
            created_at = repository.get("created_at")

            if isinstance(name, str) and isinstance(created_at, str):
                repositories.append((created_at, name))

        if len(payload) < 100:
            break

        page += 1

    repositories.sort(key=lambda item: (item[0], item[1]))
    return [name for _, name in repositories]

