import numpy as np
from scipy.spatial import Voronoi, voronoi_plot_2d
import matplotlib.pyplot as plt


def task_func(points, seed=0):
    """Calculate and plot a 2D Voronoi diagram."""

    try:
        points_array = np.asarray(points)
    except Exception as exc:
        raise TypeError("points must be array-like") from exc

    if points_array.ndim != 2 or points_array.shape[1] != 2:
        raise ValueError("points must have shape (n, 2)")

    if points_array.shape[0] < 4:
        raise ValueError("at least four points are required")

    if np.iscomplexobj(points_array):
        raise TypeError("points must contain real numeric values")

    if not np.issubdtype(points_array.dtype, np.number):
        raise TypeError("points must contain numeric values")

    try:
        points_array = np.asarray(points_array, dtype=float)
    except (TypeError, ValueError, OverflowError) as exc:
        raise TypeError("points must contain real numeric values") from exc

    if not np.all(np.isfinite(points_array)):
        raise ValueError("points must contain only finite values")

    rng = np.random.default_rng(seed)
    jitter = rng.normal(0.0, 1e-10, size=points_array.shape)
    jittered_points = points_array + jitter

    vor = Voronoi(jittered_points)

    _, ax = plt.subplots()
    voronoi_plot_2d(vor, ax=ax)

    return vor, ax

