import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    if "value" not in df.columns or isinstance(df["value"], pd.DataFrame):
        raise ValueError("df must contain exactly one 'value' column")

    if not isinstance(freq, str):
        raise ValueError("freq must be a valid frequency string")

    try:
        offset = pd.tseries.frequencies.to_offset(freq)
    except (ValueError, TypeError, AttributeError) as exc:
        raise ValueError("freq must be a valid frequency string") from exc

    if not isinstance(decomposition_model, str) or decomposition_model not in {
        "additive",
        "multiplicative",
    }:
        raise ValueError(
            "decomposition_model must be 'additive' or 'multiplicative'"
        )

    if not isinstance(df.index, pd.DatetimeIndex):
        raise ValueError("df must have a DatetimeIndex")

    if df.empty or df.index.hasnans:
        raise ValueError("df must contain valid timestamps")

    if df.index.has_duplicates or not df.index.is_monotonic_increasing:
        raise ValueError("The index must be unique and sorted")

    try:
        expected_index = pd.date_range(
            start=df.index[0],
            periods=len(df.index),
            freq=offset,
        )
    except (ValueError, TypeError) as exc:
        raise ValueError("Invalid time index or frequency") from exc

    if not df.index.equals(expected_index):
        raise ValueError("The time index must be regular and match freq")

    values = df["value"]

    if (
        not pd.api.types.is_numeric_dtype(values)
        or pd.api.types.is_bool_dtype(values)
        or pd.api.types.is_complex_dtype(values)
    ):
        raise ValueError("'value' must contain numeric data")

    try:
        numeric_values = values.astype("float64")
    except (TypeError, ValueError) as exc:
        raise ValueError("'value' must contain numeric data") from exc

    if numeric_values.isna().any():
        raise ValueError("'value' must not contain missing values")

    if (numeric_values.abs() == float("inf")).any():
        raise ValueError("'value' must contain finite values")

    if decomposition_model == "multiplicative" and (numeric_values <= 0).any():
        raise ValueError(
            "Multiplicative decomposition requires strictly positive values"
        )

    offset_type = type(offset).__name__.lower()
    n = int(getattr(offset, "n", 1))

    if "week" in offset_type:
        base_period = 52
    elif "quarter" in offset_type:
        base_period = 4
    elif "month" in offset_type:
        base_period = 12
    elif "year" in offset_type:
        base_period = 1
    elif "business" in offset_type:
        base_period = 5
    elif "day" in offset_type:
        base_period = 7
    elif "hour" in offset_type:
        base_period = 24
    elif "minute" in offset_type:
        base_period = 1440
    elif "second" in offset_type:
        base_period = 86400
    elif "milli" in offset_type:
        base_period = 86400000
    else:
        raise ValueError("Unable to determine a valid seasonal period")

    if base_period % n != 0:
        raise ValueError("Unable to determine a valid seasonal period")

    period = base_period // n

    if period < 2 or len(numeric_values) < 2 * period:
        raise ValueError("The series is too short for seasonal decomposition")

    result = seasonal_decompose(
        numeric_values,
        model=decomposition_model,
        period=period,
    )

    figure = result.plot()
    axes = figure.axes

    if not axes:
        raise ValueError("Decomposition plot contains no Axes")

    return result, axes[0]

