import re
from datetime import time


def task_func(logs: list):
    error_pattern = re.compile(r"\berror\b", re.IGNORECASE)
    timestamp_pattern = re.compile(r"\b(\d{2}):(\d{2}):(\d{2})\b")

    error_times = []

    for log in logs:
        log_text = str(log)

        if not error_pattern.search(log_text):
            continue

        for match in timestamp_pattern.finditer(log_text):
            hours, minutes, seconds = map(int, match.groups())

            if hours < 24 and minutes < 60 and seconds < 60:
                error_times.append(time(hours, minutes, seconds))

    if not error_times:
        return {"list": [], "time": None}

    total_seconds = sum(
        current_time.hour * 3600
        + current_time.minute * 60
        + current_time.second
        for current_time in error_times
    )

    average_seconds = round(total_seconds / len(error_times))

    return {
        "list": error_times,
        "time": time(
            average_seconds // 3600,
            (average_seconds % 3600) // 60,
            average_seconds % 60,
        ),
    }

