import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    directory = Path(dir_path)

    if not directory.is_dir():
        raise FileNotFoundError(dir_path)

    valid_predicates = []
    seen = set()

    for predicate in predicates or []:
        if isinstance(predicate, str):
            try:
                regex = re.compile(predicate)
            except re.error:
                continue
            key = (regex.pattern, regex.flags)
        elif isinstance(predicate, re.Pattern):
            regex = predicate
            key = (regex.pattern, regex.flags)
        else:
            continue

        if key not in seen:
            seen.add(key)
            valid_predicates.append((predicate, regex))

    if not valid_predicates:
        raise ValueError("No valid predicates provided")

    return {
        item_name: {
            predicate: bool(regex.search(item_name))
            for predicate, regex in valid_predicates
        }
        for item_name in os.listdir(directory)
    }

