import re


def task_func(target_words, n_sentences, vocabulary):
    if n_sentences < 0:
        raise ValueError("n_sentences must not be negative")
    if not vocabulary:
        raise ValueError("vocabulary must not be empty")

    targets = []
    for target in target_words:
        parts = str(target).strip().lower().split()
        if parts:
            targets.append(parts)

    targets.sort(key=len, reverse=True)

    matcher = None
    if targets:
        patterns = [
            r"(?<!\w)" + r"\s+".join(map(re.escape, parts)) + r"(?!\w)"
            for parts in targets
        ]
        matcher = re.compile("|".join(patterns))

    sentences = []
    for _ in range(n_sentences):
        sentence = " ".join(
            random.choice(vocabulary) for _ in range(10)
        ).lower()

        if matcher:
            sentence = matcher.sub(
                lambda match: re.sub(r"\s+", "_", match.group(0)),
                sentence,
            )

        sentences.append(sentence)

    return sentences

