import ast
import re


def task_func(text_file: str) -> list:
    with open(text_file, "r", encoding="utf-8") as file:
        text = file.read()

    dictionaries = []

    def find_end(start: int) -> int | None:
        depth = 0
        index = start

        while index < len(text):
            char = text[index]

            if char in ("'", '"'):
                quote = char
                if text.startswith(char * 3, index):
                    quote = char * 3

                index += len(quote)
                while index < len(text):
                    if text[index] == "\\":
                        index += 2
                    elif text.startswith(quote, index):
                        index += len(quote)
                        break
                    else:
                        index += 1
                continue

            if char == "{":
                depth += 1
            elif char == "}":
                depth -= 1
                if depth == 0:
                    return index + 1

            index += 1

        return None

    for match in re.finditer(r"\{", text):
        end = find_end(match.start())
        if end is None:
            continue

        try:
            value = ast.literal_eval(text[match.start():end])
        except (SyntaxError, ValueError):
            continue

        if isinstance(value, dict):
            dictionaries.append(value)

    return dictionaries

