from numbers import Integral, Real


def task_func(n_data_points=5000, min_value=0.0, max_value=10.0):
    """Generate truncated random data and calculate mean, median, and mode."""

    if isinstance(n_data_points, bool) or not isinstance(n_data_points, Integral):
        raise TypeError("n_data_points must be a non-negative integer")
    if n_data_points < 0:
        raise ValueError("n_data_points must be non-negative")

    if isinstance(min_value, bool) or not isinstance(min_value, Real):
        raise TypeError("min_value must be a real number")
    if isinstance(max_value, bool) or not isinstance(max_value, Real):
        raise TypeError("max_value must be a real number")
    if not math.isfinite(min_value) or not math.isfinite(max_value):
        raise ValueError("min_value and max_value must be finite")
    if min_value > max_value:
        raise ValueError("min_value must not exceed max_value")

    if n_data_points == 0:
        nan = float("nan")
        return {"mean": nan, "median": nan, "mode": nan}

    data = [
        int(random.uniform(min_value, max_value) * 1000) / 1000
        for _ in range(n_data_points)
    ]

    series = pd.Series(data)
    mode_result = stats.mode(series, keepdims=False)

    return {
        "mean": series.mean(),
        "median": series.median(),
        "mode": mode_result.mode,
    }

