import random
import math
from numbers import Real


def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    if isinstance(epoch_milliseconds, bool) or not isinstance(
        epoch_milliseconds, Real
    ):
        raise TypeError("epoch_milliseconds must be numeric")

    if not math.isfinite(epoch_milliseconds):
        raise ValueError("epoch_milliseconds must be finite")

    try:
        start_datetime = datetime.fromtimestamp(epoch_milliseconds / 1000)
    except (OverflowError, OSError, ValueError) as exc:
        raise ValueError("Invalid epoch timestamp") from exc

    current_datetime = datetime.now()

    if start_datetime > current_datetime:
        raise ValueError("epoch_milliseconds cannot represent a future time")

    if isinstance(products, (str, bytes)):
        raise TypeError("products must be an iterable of product names")

    try:
        product_list = list(products)
    except TypeError as exc:
        raise TypeError("products must be an iterable of product names") from exc

    if not product_list:
        raise ValueError("products must not be empty")

    if not all(isinstance(product, str) for product in product_list):
        raise TypeError("Every product must be a string")

    random.seed(random_seed)

    rows = []
    current_date = start_datetime.date()
    end_date = current_datetime.date()

    while current_date <= end_date:
        date_value = datetime.combine(current_date, datetime.min.time())

        for product in product_list:
            rows.append(
                {
                    "Product": product,
                    "Date": date_value,
                    "Sales": random.randint(10, 50),
                }
            )

        current_date += timedelta(days=1)

    return pd.DataFrame(rows, columns=["Product", "Date", "Sales"])

