import numpy as np


def task_func(df):
    def empty_axes():
        _, ax = plt.subplots()
        return ax

    if (
        not hasattr(df, "columns")
        or "Title" not in df.columns
        or "Content" not in df.columns
    ):
        return empty_axes()

    title_pattern = re.compile(r"\b(?:how|what)\b", re.IGNORECASE)
    matching_contents = []

    for title, content in zip(df["Title"], df["Content"]):
        title_text = "" if title is None else str(title)

        if not title_pattern.search(title_text):
            continue

        if content is None:
            content_text = ""
        else:
            try:
                content_text = "" if np.isnan(content) else str(content)
            except (TypeError, ValueError):
                content_text = str(content)

        matching_contents.append(content_text)

    if not matching_contents:
        return empty_axes()

    vectorizer = TfidfVectorizer()

    try:
        tfidf_matrix = vectorizer.fit_transform(matching_contents)
    except ValueError:
        return empty_axes()

    if tfidf_matrix.shape[1] == 0:
        return empty_axes()

    feature_names = vectorizer.get_feature_names_out()
    scores = np.asarray(tfidf_matrix.mean(axis=0)).ravel()

    _, ax = plt.subplots()
    positions = np.arange(len(feature_names))

    ax.bar(positions, scores)
    ax.set_ylabel("TF-IDF Score")
    ax.set_xticks(positions)
    ax.set_xticklabels(feature_names, rotation=90)

