from gensim.models import Word2Vec

# Constants
ALPHANUMERIC = re.compile('[\W_]+')


def task_func(texts, stopwords=None):
    """Train and return a Word2Vec model from a collection of texts."""
    if isinstance(texts, str):
        raise TypeError("texts must be an iterable of strings, not a single string")

    try:
        texts = list(texts)
    except TypeError as exc:
        raise TypeError("texts must be an iterable of strings") from exc

    if not texts:
        raise ValueError("texts must not be empty")

    if stopwords is None:
        stopword_set = {
            word.lower()
            for word in nltk.corpus.stopwords.words("english")
        }
    else:
        if isinstance(stopwords, str):
            raise TypeError("stopwords must be an iterable of strings, not a string")

        try:
            stopword_items = list(stopwords)
        except TypeError as exc:
            raise TypeError("stopwords must be an iterable of strings") from exc

        for word in stopword_items:
            if not isinstance(word, str):
                raise TypeError("stopwords must contain only strings")

        stopword_set = {word.lower() for word in stopword_items}

    sentences = []

    for index, text in enumerate(texts):
        if not isinstance(text, str):
            raise TypeError(f"texts[{index}] must be a string")

        cleaned = ALPHANUMERIC.sub(" ", text.lower())
        tokens = [
            token for token in cleaned.split()
            if token not in stopword_set
        ]

        if tokens:
            sentences.append(tokens)

    if not sentences:
        raise ValueError(
            "texts contain no tokens after cleaning and stopword removal"
        )

    return Word2Vec(
        sentences=sentences,
        vector_size=100,
        window=5,
        min_count=1,
        workers=1,
        seed=42,
    )

