def task_func(df, tuples, n_plots):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    missing_columns = [column for column in COLUMNS if column not in df.columns]
    if missing_columns:
        raise KeyError(f"Missing columns: {missing_columns}")

    if isinstance(n_plots, bool) or not isinstance(n_plots, int):
        raise TypeError("n_plots must be a non-negative integer")
    if n_plots < 0:
        raise ValueError("n_plots must be non-negative")

    try:
        row_tuples = list(tuples)
    except TypeError as exc:
        raise TypeError("tuples must be an iterable of row-value tuples") from exc

    for values in row_tuples:
        if not isinstance(values, (tuple, list)):
            raise TypeError("Each row specification must be a tuple or list")
        if len(values) != len(COLUMNS):
            raise ValueError(
                f"Each tuple must contain {len(COLUMNS)} values"
            )

    filtered_df = df.copy()

    for values in row_tuples:
        mask = pd.Series(True, index=filtered_df.index)

        for column, value in zip(COLUMNS, values):
            column_mask = filtered_df[column].eq(value).fillna(False)
            if pd.isna(value):
                column_mask |= filtered_df[column].isna()
            mask &= column_mask

        filtered_df = filtered_df.loc[~mask]

    column_pairs = list(combinations(COLUMNS, 2))
    if n_plots > len(column_pairs):
        raise ValueError(f"n_plots cannot exceed {len(column_pairs)}")

    axes = []
    for x_column, y_column in sample(column_pairs, n_plots):
        axes.append(
            sns.scatterplot(
                data=filtered_df,
                x=x_column,
                y=y_column,
            )
        )

    return filtered_df, axes

