import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    if buffer_size < 1:
        raise ValueError("buffer_size must be at least 1")

    duration = float(run_duration)
    started_at = datetime.now()

    if duration <= 0:
        return "Server stopped after 0.00 seconds."

    server_socket = None
    clients = set()
    writable = set()
    outgoing = {}
    pending = {}

    def close_client(client):
        clients.discard(client)
        writable.discard(client)
        outgoing.pop(client, None)
        pending.pop(client, None)
        try:
            client.close()
        except OSError:
            pass

    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((server_address, server_port))
        server_socket.listen()
        server_socket.setblocking(False)

        deadline = started_at + timedelta(seconds=duration)

        while datetime.now() < deadline:
            remaining = (deadline - datetime.now()).total_seconds()
            if remaining <= 0:
                break

            readable = [server_socket, *clients]
            writable_sockets = list(writable)
            exceptional = [server_socket, *clients]

            try:
                ready_read, ready_write, ready_exceptional = select.select(
                    readable, writable_sockets, exceptional, remaining
                )
            except InterruptedError:
                continue
            except (OSError, ValueError):
                break

            if server_socket in ready_exceptional:
                break

            for client in ready_exceptional:
                if client in clients:
                    close_client(client)

            if server_socket in ready_read:
                while True:
                    try:
                        client, _ = server_socket.accept()
                        client.setblocking(False)
                        clients.add(client)
                        outgoing[client] = queue.Queue()
                    except BlockingIOError:
                        break
                    except OSError:
                        break

            for client in ready_read:
                if client not in clients:
                    continue

                try:
                    data = client.recv(buffer_size)
                    if not data:
                        close_client(client)
                        continue

                    response = data + datetime.now().isoformat().encode()
                    outgoing[client].put(response)
                    writable.add(client)
                except BlockingIOError:
                    continue
                except OSError:
                    close_client(client)

            for client in ready_write:
                if client not in clients:
                    continue

                try:
                    data = pending.get(client)

                    if not data:
                        try:
                            data = outgoing[client].get_nowait()
                        except queue.Empty:
                            writable.discard(client)
                            continue

                    sent = client.send(data)

                    if sent < len(data):
                        pending[client] = data[sent:]
                    else:
                        pending.pop(client, None)

                    if (
                        client not in pending
                        and outgoing[client].empty()
                    ):
                        writable.discard(client)
                except BlockingIOError:
                    continue
                except OSError:
                    close_client(client)

        elapsed = (datetime.now() - started_at).total_seconds()
        return f"Server stopped after {elapsed:.2f} seconds."

    except OSError as error:
        elapsed = (datetime.now() - started_at).total_seconds()
        return f"Server failed after {elapsed:.2f} seconds: {error}"

    finally:
        for client in list(clients):
            close_client(client)

        if server_socket is not None:
            try:
                server_socket.close()
            except OSError:
                pass

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from matplotlib.lines import Line2D
from numbers import Integral


def task_func(N=100, CATEGORIES=["A", "B", "C", "D", "E"], seed=42):
    if isinstance(N, bool) or not isinstance(N, Integral) or N < 0:
        raise ValueError("N must be a non-negative integer")

    categories = list(CATEGORIES)
    if not categories:
        raise ValueError("CATEGORIES must not be empty")

    try:
        if len(set(categories)) != len(categories):
            raise ValueError("CATEGORIES must contain unique values")
    except TypeError as exc:
        raise TypeError("Categories must be hashable") from exc

    rng = np.random.default_rng(seed)
    category_count = len(categories)

    if N < category_count:
        selected_categories = rng.choice(
            categories, size=N, replace=False
        ).tolist()
    else:
        selected_categories = categories.copy()
        selected_categories.extend(
            rng.choice(
                categories,
                size=N - category_count,
                replace=True,
            ).tolist()
        )
        rng.shuffle(selected_categories)

    dataframe = pd.DataFrame(
        {
            "x": rng.random(N),
            "y": rng.random(N),
            "category": selected_categories,
        }
    )

    figure, axes = plt.subplots()
    category_to_index = {
        category: index for index, category in enumerate(categories)
    }

    if N:
        color_indices = np.array(
            [category_to_index[category] for category in selected_categories]
        )
        axes.scatter(
            dataframe["x"],
            dataframe["y"],
            c=color_indices,
            cmap="tab20",
            vmin=0,
            vmax=max(category_count - 1, 1),
        )
    else:
        axes.scatter([], [])

    colormap = plt.get_cmap("tab20")
    legend_handles = [
        Line2D(
            [0],
            [0],
            marker="o",
            color="w",
            label=str(category),
            markerfacecolor=colormap(
                index / max(category_count - 1, 1)
            ),
            markersize=7,
        )
        for index, category in enumerate(categories)
    ]

    axes.set_xlabel("x")
    axes.set_ylabel("y")
    axes.legend(handles=legend_handles, title="category")

    return dataframe, axes

import pandas as pd
import numpy as np
import codecs
import re
import datetime


def task_func(start_year=1980, end_year=2000, email_domain='example.com',
              latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
              other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
              rng_seed=None):
    if isinstance(start_year, bool) or isinstance(end_year, bool):
        raise TypeError("Years must be integers.")

    if not isinstance(start_year, (int, np.integer)) or not isinstance(
        end_year, (int, np.integer)
    ):
        raise TypeError("Years must be integers.")

    start_year = int(start_year)
    end_year = int(end_year)

    if not 0 <= start_year <= end_year <= 9999:
        raise ValueError("Years must satisfy 0 <= start_year <= end_year <= 9999.")

    if not isinstance(email_domain, str) or not email_domain.strip():
        raise ValueError("email_domain must be a non-empty string.")

    if latin_names is None or other_names is None:
        raise TypeError("Name collections must not be None.")

    names = list(latin_names) + list(other_names)
    if not names:
        raise ValueError("At least one name must be provided.")

    if not all(isinstance(name, str) for name in names):
        raise TypeError("All names must be strings.")

    def correct_encoding(name):
        corrected = name
        for _ in range(3):
            try:
                candidate = codecs.decode(
                    corrected.encode("latin-1"), "utf-8"
                )
            except (UnicodeEncodeError, UnicodeDecodeError):
                break

            if candidate == corrected:
                break
            corrected = candidate

        return corrected

    def is_leap_year(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    rng = np.random.default_rng(rng_seed)
    records = []

    for record_id in range(1, 101):
        name = correct_encoding(
            names[int(rng.integers(0, len(names)))]
        )
        year = int(rng.integers(start_year, end_year + 1))
        month = int(rng.integers(1, 13))

        days_in_month = (
            29 if is_leap_year(year) else 28
        ) if month == 2 else [31, 30, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]

        day = int(rng.integers(1, days_in_month + 1))

        if year == 0:
            date_of_birth = (
                f"{year:04d}-{month:02d}-{day:02d} 00:00:00"
            )
        else:
            date_of_birth = datetime.datetime(year, month, day)

        records.append({
            "ID": record_id,
            "Name": name,
            "Date of Birth": date_of_birth,
            "Email": f"{name.lower()}{year}@{email_domain}",
        })

    return pd.DataFrame(
        records,
        columns=["ID", "Name", "Date of Birth", "Email"],
    )

