    if not isinstance(N, int):
        raise TypeError("N must be an integer")
    if N < 0:
        raise ValueError("N must be non-negative")

    differences = [
        (index, math.sqrt((value1 - value2) ** 2))
        for index, (value1, value2) in enumerate(zip(l1, l2))
    ]

    largest = heapq.nlargest(
        N,
        differences,
        key=lambda item: (item[1], -item[0]),
    )

    _, axes = plt.subplots()
    axes.plot(
        [index for index, _ in largest],
        [difference for _, difference in largest],
    )

    return axes

