import pandas as pd
import numpy as np
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(start_date='2016-01-01', periods=24, freq='M', model='additive'):
    model = str(model).lower()

    if model not in {'additive', 'multiplicative'}:
        raise ValueError("model must be 'additive' or 'multiplicative'")

    if isinstance(periods, bool) or not isinstance(periods, (int, np.integer)):
        raise ValueError("periods must be a positive integer")

    if periods <= 0:
        raise ValueError("periods must be positive")

    index = pd.date_range(start=start_date, periods=periods, freq=freq)
    offset_name = type(pd.tseries.frequencies.to_offset(freq)).__name__.lower()

    if 'month' in offset_name:
        seasonal_period = 12
    elif 'quarter' in offset_name:
        seasonal_period = 4
    elif 'week' in offset_name:
        seasonal_period = 52
    elif 'day' in offset_name:
        seasonal_period = 7
    elif 'hour' in offset_name:
        seasonal_period = 24
    else:
        seasonal_period = 2

    if periods < 2 * seasonal_period:
        raise ValueError(
            f"at least {2 * seasonal_period} observations are required"
        )

    t = np.arange(periods, dtype=float)
    trend = 100 + 2 * t
    seasonal_pattern = np.sin(2 * np.pi * t / seasonal_period)

    if model == 'multiplicative':
        sales = trend * (1 + 0.1 * seasonal_pattern)
    else:
        sales = trend + 10 * seasonal_pattern

    sales_series = pd.Series(sales, index=index, name='sales')

    decomposition = seasonal_decompose(
        sales_series,
        model=model,
        period=seasonal_period,
        extrapolate_trend=False,
    )

    return {
        'trend': decomposition.trend,
        'seasonal': decomposition.seasonal,
        'residual': decomposition.resid,
    }

