import numpy as np
from sklearn.decomposition import PCA
import matplotlib.pyplot as plt


def task_func(P, T, tensor_shape=(3, 3, 3)):
    if not isinstance(P, (np.ndarray, np.matrix)):
        raise TypeError("P must be a NumPy array or matrix.")
    if not isinstance(T, (np.ndarray, np.matrix)):
        raise TypeError("T must be a NumPy array or matrix.")

    P_array = np.asarray(P)
    T_array = np.asarray(T)

    if P_array.ndim != 2:
        raise ValueError("P must be a 2D matrix.")

    try:
        shape = tuple(tensor_shape)
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "tensor_shape must contain three positive integers."
        ) from exc

    if len(shape) != 3 or any(
        isinstance(dim, bool)
        or not isinstance(dim, (int, np.integer))
        or dim <= 0
        for dim in shape
    ):
        raise ValueError("tensor_shape must contain three positive integers.")

    if P_array.shape[1] != shape[0]:
        raise ValueError(
            "The first tensor dimension must match the number of columns in P."
        )

    if T_array.size != int(np.prod(shape)):
        raise ValueError("T cannot be reshaped to tensor_shape.")

    if P_array.shape[0] < 2:
        raise ValueError("P must contain at least two rows.")

    if not np.issubdtype(P_array.dtype, np.number) or not np.issubdtype(
        T_array.dtype, np.number
    ):
        raise TypeError("P and T must contain numeric values.")

    if np.issubdtype(P_array.dtype, np.complexfloating) or np.issubdtype(
        T_array.dtype, np.complexfloating
    ):
        raise TypeError("P and T must contain real numeric values.")

    if not np.all(np.isfinite(P_array)) or not np.all(np.isfinite(T_array)):
        raise ValueError("P and T must contain only finite values.")

    T_reshaped = T_array.reshape(shape)
    product = np.tensordot(P_array, T_reshaped, axes=([1], [0]))
    data = product.reshape(P_array.shape[0], -1)

    if data.shape[1] < 2:
        raise ValueError("The flattened product must have at least two features.")

    if not np.all(np.isfinite(data)):
        raise ValueError("The matrix-tensor product contains non-finite values.")

    pca_result = PCA(n_components=2).fit_transform(data)

    _, ax = plt.subplots()
    ax.scatter(pca_result[:, 0], pca_result[:, 1])
    ax.set_title("PCA Result Visualization")
    ax.set_xlabel("Principal Component 1")
    ax.set_ylabel("Principal Component 2")

    return pca_result, ax

import pandas as pd
from sklearn.linear_model import LinearRegression

DATA = {
    "Area_String": ["1,000", "2,000", "3,000", "4,000", "5,000"],
    "Price": [100, 200, 300, 400, 500],
}


def task_func(area_string, data=DATA):
    def parse_area(value):
        if value is None or pd.isna(value):
            raise ValueError("Area must be a non-empty finite number.")

        text = str(value).strip().replace(",", "")
        if not text:
            raise ValueError("Area must be a non-empty finite number.")

        try:
            number = float(text)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Invalid area value: {value!r}") from exc

        if not pd.api.types.is_number(number) or not pd.notna(number):
            raise ValueError(f"Invalid area value: {value!r}")

        return number

    frame = pd.DataFrame(data)
    required_columns = {"Area_String", "Price"}
    missing_columns = required_columns - set(frame.columns)

    if missing_columns:
        raise ValueError(
            f"Missing required columns: {', '.join(sorted(missing_columns))}"
        )
    if frame.empty:
        raise ValueError("Training data must not be empty.")

    frame = frame.copy()
    frame["Area"] = frame["Area_String"].map(parse_area)
    frame["Price"] = pd.to_numeric(frame["Price"], errors="coerce")

    if frame["Price"].isna().any():
        raise ValueError("Price values must be numeric and non-missing.")

    model = LinearRegression()
    model.fit(frame[["Area"]], frame["Price"])

    return float(model.predict([[parse_area(area_string)]])[0])

