import warnings
import os
import glob
import shutil
import time


def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    transferred_files = []

    if not os.path.isdir(SOURCE_DIR):
        warnings.warn(
            f"Source directory does not exist or is not a directory: {SOURCE_DIR}"
        )
        return transferred_files

    if isinstance(EXTENSIONS, str):
        extensions = [EXTENSIONS]
    else:
        try:
            extensions = list(EXTENSIONS)
        except TypeError:
            extensions = [EXTENSIONS]

    normalized_extensions = set()
    for extension in extensions:
        if extension is None:
            continue

        extension = str(extension).strip()
        if not extension:
            continue

        if not extension.startswith("."):
            extension = f".{extension}"

        normalized_extensions.add(extension.lower())

    if not normalized_extensions:
        return transferred_files

    try:
        os.makedirs(DEST_DIR, exist_ok=True)
    except (OSError, TypeError) as error:
        warnings.warn(
            f"Could not create destination directory '{DEST_DIR}': {error}"
        )
        return transferred_files

    if not os.path.isdir(DEST_DIR):
        warnings.warn(f"Destination is not a directory: {DEST_DIR}")
        return transferred_files

    try:
        source_paths = glob.glob(os.path.join(SOURCE_DIR, "*"))
    except (OSError, TypeError) as error:
        warnings.warn(f"Could not list source directory '{SOURCE_DIR}': {error}")
        return transferred_files

    for source_path in source_paths:
        if not os.path.isfile(source_path):
            continue

        filename = os.path.basename(source_path)
        extension = os.path.splitext(filename)[1].lower()

        if extension not in normalized_extensions:
            continue

        destination_path = os.path.join(DEST_DIR, filename)

        try:
            shutil.copy2(source_path, destination_path)
            transferred_files.append(filename)
        except Exception as error:
            warnings.warn(
                f"Could not transfer '{source_path}' to "
                f"'{destination_path}': {error}"
            )

    return transferred_files

