import subprocess
import csv
import glob
import random
import os


def task_func(file):
    chunk_size = "1000"
    prefix = None
    split_files = []

    try:
        file_path = os.fspath(file)

        if not os.path.isfile(file_path):
            return []

        if not file_path.lower().endswith(".csv"):
            return []

        directory = os.path.dirname(os.path.abspath(file_path))
        basename = os.path.splitext(os.path.basename(file_path))[0]

        counter = 0
        while True:
            prefix = os.path.join(
                directory,
                f"split_{basename}_{os.getpid()}_{counter}_",
            )
            if not glob.glob(prefix + "*"):
                break
            counter += 1

        subprocess.run(
            ["split", "-l", chunk_size, "--", file_path, prefix],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )

        split_files = sorted(
            path
            for path in glob.glob(prefix + "*")
            if os.path.isfile(path)
        )

        for split_file in split_files:
            with open(split_file, "r", newline="", encoding="utf-8") as source:
                rows = list(csv.reader(source))

            random.shuffle(rows)

            with open(split_file, "w", newline="", encoding="utf-8") as target:
                csv.writer(target).writerows(rows)

        return split_files

    except Exception:
        if prefix is not None:
            for path in glob.glob(prefix + "*"):
                try:
                    if os.path.isfile(path):
                        os.remove(path)
                except OSError:
                    pass
        return []

