import numpy as np


def task_func(samples=10, delay=0.1):
    if isinstance(samples, (bool, np.bool_)) or not isinstance(
        samples, (int, np.integer)
    ):
        raise TypeError("samples must be a positive integer")
    if samples <= 0:
        raise ValueError("samples must be positive")

    if isinstance(delay, (bool, np.bool_)) or not isinstance(
        delay, (int, float, np.integer, np.floating)
    ):
        raise TypeError("delay must be a numeric value")

    try:
        delay = float(delay)
    except (OverflowError, ValueError) as exc:
        raise ValueError("delay must be finite and non-negative") from exc

    if not np.isfinite(delay) or delay < 0:
        raise ValueError("delay must be finite and non-negative")

    delays = []
    for _ in range(samples):
        start = time.perf_counter()
        time.sleep(delay)
        delays.append(time.perf_counter() - start)

    measured_delays = np.asarray(delays, dtype=float)
    return float(np.mean(measured_delays)), float(np.std(measured_delays))

import cv2
import numpy as np
import os
from sklearn.cluster import KMeans


def task_func(image_path='image.jpg', n_clusters=3, random_seed=42):
    if isinstance(n_clusters, bool) or not isinstance(n_clusters, (int, np.integer)):
        raise ValueError("'n_clusters' must be a positive integer")
    if n_clusters <= 0:
        raise ValueError("'n_clusters' must be a positive integer")

    if not os.path.isfile(image_path):
        raise FileNotFoundError(image_path)

    image_bgr = cv2.imread(image_path, cv2.IMREAD_COLOR)
    if image_bgr is None:
        raise ValueError(f"Unable to read image: {image_path}")

    original = cv2.cvtColor(image_bgr, cv2.COLOR_BGR2RGB)

    if original.ndim != 3 or original.shape[2] != 3:
        raise ValueError("The input image must be an RGB image")
    if original.shape[0] == 0 or original.shape[1] == 0:
        raise ValueError("The input image must not be empty")

    pixels = original.reshape(-1, 3).astype(np.float32)

    if n_clusters > len(pixels):
        raise ValueError("'n_clusters' cannot exceed the number of image pixels")

    model = KMeans(
        n_clusters=int(n_clusters),
        random_state=random_seed,
        n_init=10,
    )
    labels = model.fit_predict(pixels)

    if n_clusters == 1:
        segmented = original.copy()
        centroids = original.reshape(-1, 3).mean(axis=0).round().astype(np.uint8)
        centroids = centroids.reshape(1, 3)
    else:
        centroids = np.clip(
            np.rint(model.cluster_centers_), 0, 255
        ).astype(np.uint8)
        segmented = centroids[labels].reshape(original.shape)

    base_name = os.path.splitext(os.path.basename(os.fspath(image_path)))[0]
    output_dir = os.path.join(
        os.path.dirname(os.path.abspath(os.fspath(image_path))),
        f"{base_name}_clusters",
    )
    os.makedirs(output_dir, exist_ok=True)

    for cluster_index in range(int(n_clusters)):
        region = np.zeros_like(original)
        mask = labels == cluster_index

        if n_clusters == 1:
            region[mask.reshape(original.shape[:2])] = original[
                mask.reshape(original.shape[:2])
            ]
        else:
            region.reshape(-1, 3)[mask] = centroids[cluster_index]

        output_path = os.path.join(
            output_dir,
            f"{base_name}_cluster_{cluster_index}.png",
        )

        if not cv2.imwrite(
            output_path,
            cv2.cvtColor(region, cv2.COLOR_RGB2BGR),
        ):
            raise IOError(f"Unable to save image: {output_path}")

    return original, segmented

import re
import os
from pathlib import Path
import csv


def task_func(directory: str, pattern: str = r'^(.*?)-\d+\.csv$') -> list:
    directory_path = Path(directory)

    if not directory_path.exists():
        raise FileNotFoundError(directory)
    if not directory_path.is_dir():
        raise NotADirectoryError(directory)

    regex = re.compile(pattern)
    new_files = []

    for source in sorted(directory_path.iterdir(), key=lambda path: path.name):
        if not source.is_file():
            continue

        match = regex.match(source.name)
        if match is None:
            continue

        base_name = match.group(1) if match.lastindex else source.stem
        target = directory_path / f"{base_name}.csv"

        if target == source or target.exists():
            continue

        target.write_bytes(source.read_bytes())
        new_files.append(target.name)

    return sorted(new_files)

