import pandas as pd
import numpy as np
from sklearn.preprocessing import LabelEncoder


def task_func(
    num_samples,
    countries=['Russia', 'China', 'USA', 'India', 'Brazil'],
    ages=np.arange(18, 60),
    genders=['Male', 'Female'],
    rng_seed=None,
):
    if isinstance(num_samples, (bool, np.bool_)) or not isinstance(
        num_samples, (int, np.integer)
    ):
        raise ValueError("num_samples must be an integer")

    if num_samples < 0:
        raise ValueError("num_samples must be non-negative")

    rng = np.random.default_rng(rng_seed)

    sampled_countries = rng.choice(countries, size=num_samples)
    sampled_ages = rng.choice(ages, size=num_samples)
    sampled_genders = rng.choice(genders, size=num_samples)

    encoder = LabelEncoder()
    encoder.fit(genders)
    encoded_genders = encoder.transform(sampled_genders)

    return pd.DataFrame(
        {
            "Country": sampled_countries,
            "Age": sampled_ages,
            "Gender": encoded_genders,
        }
    )

import numpy as np
import pandas as pd


def task_func(num_teams=5, num_games=100):
    """Generate random scores for each team across multiple games."""
    if isinstance(num_teams, bool) or not isinstance(num_teams, (int, np.integer)):
        raise ValueError("num_teams must be a non-negative integer")
    if isinstance(num_games, bool) or not isinstance(num_games, (int, np.integer)):
        raise ValueError("num_games must be a non-negative integer")
    if num_teams < 0 or num_games < 0:
        raise ValueError("num_teams and num_games must be non-negative")

    scores = np.random.randint(0, 101, size=(num_teams, num_games))
    teams = [f"Team {i}" for i in range(1, num_teams + 1)]
    games = [f"Game {i}" for i in range(1, num_games + 1)]

    return pd.DataFrame(scores, index=teams, columns=games)

import numpy as np
import cv2
import os

def task_func(image_path='image.jpg', threshold=128):
    if not os.path.isfile(image_path):
        raise FileNotFoundError(f"Image file not found: {image_path}")

    if isinstance(threshold, (bool, np.bool_)) or not isinstance(
        threshold, (int, np.integer)
    ):
        raise ValueError("threshold must be an integer from 0 to 255")

    threshold = int(threshold)
    if not 0 <= threshold <= 255:
        raise ValueError("threshold must be an integer from 0 to 255")

    original_image = cv2.imread(image_path, cv2.IMREAD_GRAYSCALE)
    if original_image is None:
        raise ValueError(f"Unable to read image: {image_path}")

    _, binary_image = cv2.threshold(
        original_image, threshold, 255, cv2.THRESH_BINARY
    )

    if not cv2.imwrite("binary_image.jpg", binary_image):
        raise IOError("Failed to save binary_image.jpg")

    return original_image, binary_image

import binascii
import numpy as np
import matplotlib.pyplot as plt
import pandas as pd


def task_func(hex_str):
    if not isinstance(hex_str, str):
        raise ValueError("hex_str must be a valid hex string")

    if hex_str.startswith("\\x"):
        hex_str = hex_str[2:]

    if not hex_str:
        raise ValueError("hex_str must not be empty")

    try:
        byte_data = binascii.unhexlify(hex_str)
    except (binascii.Error, ValueError, TypeError) as exc:
        raise ValueError("hex_str is not a valid hex string") from exc

    byte_values = np.frombuffer(byte_data, dtype=np.uint8)
    frequencies = np.bincount(byte_values, minlength=256)

    dataframe = pd.DataFrame(
        {
            "Byte Value": np.arange(256),
            "Frequency": frequencies,
        }
    )

    _, axes = plt.subplots()
    axes.bar(dataframe["Byte Value"], dataframe["Frequency"])
    axes.set_xlabel("Byte Value")
    axes.set_ylabel("Frequency")

    return dataframe, axes

import binascii
