import re
import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    if pattern == "":
        return df.copy(deep=True)

    regex = re.compile(pattern)

    def reorder_words(value):
        if not isinstance(value, str):
            return value

        words = value.split()
        matching_words = [word for word in words if regex.search(word)]
        reversed_matches = iter(reversed(matching_words))

        return " ".join(
            next(reversed_matches) if regex.search(word) else word
            for word in words
        )

    result = df.copy()
    result[column_name] = result[column_name].apply(reorder_words)
    return result

