# Constants
VEGETABLES = ['Carrot', 'Potato', 'Tomato', 'Cabbage', 'Spinach']


def task_func(vegetable_dict, seed=0):
    """Calculate random count and percentage statistics for preferred vegetables."""
    if not isinstance(vegetable_dict, dict):
        raise TypeError("vegetable_dict must be a dictionary")

    reversed_dict = {
        vegetable: person
        for person, vegetable in vegetable_dict.items()
    }

    vegetables = list(reversed_dict)
    rng = random.Random(seed)
    counts = [rng.randint(1, 10) for _ in vegetables]
    total_count = sum(counts)

    percentages = [
        count / total_count * 100
        for count in counts
    ]

    return pd.DataFrame(
        {
            "Vegetable": vegetables,
            "Count": counts,
            "Percentage": percentages,
        }
    )

import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str},
        },
        "required": ["name", "age", "email"],
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$",
):
    if not isinstance(file_path, (str, os.PathLike)) or not os.path.isfile(file_path):
        raise ValueError("JSON file does not exist")

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError("Unable to read valid JSON") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON root must be an object")

    if not isinstance(INPUT_JSON, dict):
        raise ValueError("Invalid schema")

    properties = INPUT_JSON.get("properties")
    required = INPUT_JSON.get("required")

    if not isinstance(properties, dict) or not isinstance(required, list):
        raise ValueError("Invalid schema")

    for name in required:
        if not isinstance(name, str):
            raise ValueError("Invalid schema")
        if name not in data:
            raise ValueError(f"Missing required attribute: {name}")

    for name, definition in properties.items():
        if not isinstance(name, str) or not isinstance(definition, dict):
            raise ValueError("Invalid schema")
        if "type" not in definition:
            raise ValueError("Invalid schema")

        expected_type = definition["type"]
        valid_types = (
            expected_type
            if isinstance(expected_type, tuple)
            else (expected_type,)
        )

        if not valid_types or not all(
            isinstance(item, type) for item in valid_types
        ):
            raise ValueError("Invalid schema")

        if name in data:
            value = data[name]
            if (
                isinstance(value, bool)
                and int in valid_types
                and bool not in valid_types
            ):
                raise ValueError(f"Invalid type for attribute: {name}")
            if not isinstance(value, valid_types):
                raise ValueError(f"Invalid type for attribute: {name}")

    if "email" in data:
        if not isinstance(data["email"], str):
            raise ValueError("Invalid email type")
        try:
            if re.fullmatch(EMAIL_REGEX, data["email"]) is None:
                raise ValueError("Invalid email format")
        except re.error as exc:
            raise ValueError("Invalid email regular expression") from exc

    if not isinstance(attribute, str) or attribute not in data:
        raise ValueError(f"Missing attribute: {attribute}")

    return data[attribute]

