import pytz
from dateutil import parser


def task_func(date_str, from_tz, to_tz):
    source_timezone = pytz.timezone(from_tz)
    target_timezone = pytz.timezone(to_tz)
    datetime_value = parser.parse(date_str)

    if datetime_value.tzinfo is None:
        datetime_value = source_timezone.localize(datetime_value)
    else:
        datetime_value = datetime_value.astimezone(source_timezone)

    return datetime_value.astimezone(target_timezone).strftime("%Y-%m-%d %H:%M:%S")

import numpy as np
from itertools import combinations


def task_func(array1, array2):
    array1 = np.asarray(array1)
    array2 = np.asarray(array2)

    if len(array1) != len(array2):
        raise ValueError("Input arrays must have the same length.")

    points = list(zip(array1, array2))

    if len(points) < 2:
        return 0.0

    return float(
        max(
            np.linalg.norm(np.asarray(point_a) - np.asarray(point_b))
            for point_a, point_b in combinations(points, 2)
        )
    )

