import pandas as pd
import random
import re


def task_func(person_names, email_domains, num_records=5):
    if num_records < 0:
        raise ValueError("num_records cannot be negative")

    if len(person_names) < num_records:
        raise ValueError("Not enough names for the requested number of records")

    domains = list(email_domains)
    if not domains:
        raise ValueError("At least one email domain is required")

    selected_names = random.sample(person_names, num_records)
    records = []

    for name in selected_names:
        local_part = re.sub(r"[^a-z0-9]+", ".", str(name).lower()).strip(".")
        local_part = local_part or "user"

        domain = random.choice(domains)
        email = f"{local_part}@{domain}".replace("@", "[at]")

        records.append({"Name": name, "Email": email})

    return pd.DataFrame(records, columns=["Name", "Email"])

import ssl
import os
import hashlib


def task_func(client_socket, cert_file, key_file, buffer_size=1024):
    try:
        if isinstance(buffer_size, bool) or not isinstance(buffer_size, int):
            raise ValueError("buffer_size must be a positive integer")
        if buffer_size <= 0:
            raise ValueError("buffer_size must be a positive integer")

        context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        context.load_cert_chain(certfile=cert_file, keyfile=key_file)
        secure_socket = context.wrap_socket(client_socket, server_side=True)

        requested_path = secure_socket.recv(buffer_size).decode("utf-8").strip()
        if not requested_path:
            raise ValueError("empty file path")

        if not os.path.isfile(requested_path):
            result = "File not found"
        else:
            digest = hashlib.sha256()
            with open(requested_path, "rb") as file:
                while True:
                    chunk = file.read(buffer_size)
                    if not chunk:
                        break
                    digest.update(chunk)
            result = digest.hexdigest()

        secure_socket.sendall(result.encode("utf-8"))
        return result
    except Exception as exc:
        return f"Error: {exc}"

from random import shuffle, randint
import pandas as pd


def task_func(l, n_groups=5):
    """Return repeated, shuffled strings with randomly rotated characters."""
    if not isinstance(l, list):
        raise TypeError("l must be a list")
    if not isinstance(n_groups, int) or isinstance(n_groups, bool):
        raise TypeError("n_groups must be an integer")
    if n_groups < 0:
        raise ValueError("n_groups must be non-negative")
    if not all(isinstance(value, str) for value in l):
        raise TypeError("all elements of l must be strings")

    shuffled = l.copy()
    shuffle(shuffled)

    result = []
    for index in range(len(shuffled) * n_groups):
        value = shuffled[index % len(shuffled)]
        n = randint(0, len(value))
        result.append(value[n:] + value[:n])

    return pd.Series(result)

import requests
from bs4 import BeautifulSoup
import pandas as pd


def task_func(url="http://example.com"):
    response = requests.get(url)
    response.raise_for_status()

    try:
        soup = BeautifulSoup(response.text, "html.parser")
    except Exception as exc:
        raise ValueError("Unable to parse page content") from exc

    table = soup.find("table")
    if table is None:
        raise ValueError("No table found on the page")

    headers = None
    header_row = table.find("tr", lambda row: row.find("th") is not None)

    if header_row is not None:
        headers = [
            cell.get_text(" ", strip=True)
            for cell in header_row.find_all("th")
        ]

    rows = []
    for row in table.find_all("tr"):
        cells = row.find_all("td")
        if cells:
            rows.append([
                cell.get_text(" ", strip=True)
                for cell in cells
            ])

    if not rows:
        raise ValueError("No table data found")

    try:
        dataframe = pd.DataFrame(rows)
    except Exception as exc:
        raise ValueError("Unable to create DataFrame") from exc

    if headers and len(headers) == len(dataframe.columns):
        dataframe.columns = headers

    return dataframe

import shutil
from pathlib import Path
from typing import List


def task_func(source_dir: str, target_dir: str, extensions: List[str]) -> int:
    source = Path(source_dir)
    target = Path(target_dir)

    if not source.is_dir() or not target.is_dir():
        raise ValueError("source_dir and target_dir must exist and be directories")

    normalized_extensions = {
        extension.lower() if extension.startswith(".") else f".{extension.lower()}"
        for extension in extensions
    }

    moved_count = 0

    for file_path in source.iterdir():
        if (
            file_path.is_file()
            and not file_path.is_symlink()
            and file_path.suffix.lower() in normalized_extensions
        ):
            shutil.move(str(file_path), str(target / file_path.name))
            moved_count += 1

    return moved_count

import pandas as pd
import folium
from geopy.geocoders import Photon

import math
from collections.abc import Sequence


def task_func(dic):
    if not hasattr(dic, "items"):
        raise TypeError("dic must be dictionary-like")

    geolocator = Photon(user_agent="geoapiExercises")
    locations = []

    def parse_coordinates(value):
        if isinstance(value, str):
            parts = [part.strip() for part in value.split(",")]
            if len(parts) != 2:
                return None
            value = parts

        if isinstance(value, (str, bytes)) or not isinstance(value, Sequence):
            return None

        if len(value) != 2:
            return None

        try:
            latitude = float(value[0])
            longitude = float(value[1])
        except (TypeError, ValueError):
            return None

        if (
            not math.isfinite(latitude)
            or not math.isfinite(longitude)
            or not -90 <= latitude <= 90
            or not -180 <= longitude <= 180
        ):
            return None

        return latitude, longitude

    for name, value in dic.items():
        coordinates = parse_coordinates(value)

        if coordinates is None and isinstance(value, str):
            try:
                result = geolocator.geocode(value)
                if result is not None:
                    coordinates = parse_coordinates(
                        (result.latitude, result.longitude)
                    )
            except Exception:
                coordinates = None

        if coordinates is not None:
            locations.append((name, coordinates))

    if locations:
        center = [
            sum(latitude for _, (latitude, _) in locations) / len(locations),
            sum(longitude for _, (_, longitude) in locations) / len(locations),
        ]
    else:
        center = [0, 0]

    map_object = folium.Map(location=center, zoom_start=2)

    for name, (latitude, longitude) in locations:
        folium.Marker(
            location=[latitude, longitude],
            popup=str(name),
            tooltip=str(name),
        ).add_to(map_object)

    return map_object

import numpy as np
import matplotlib.pyplot as plt
import numbers

# Constants
COLORS = ['r', 'g', 'b']


def task_func(df, group_col, value_col):
    if group_col not in df.columns:
        raise KeyError(group_col)
    if value_col not in df.columns:
        raise KeyError(value_col)

    values = df[value_col]
    missing_values = values.isna().to_numpy()

    for value, is_missing in zip(values, missing_values):
        if not is_missing:
            if (
                isinstance(value, (bool, np.bool_))
                or not isinstance(value, numbers.Number)
            ):
                raise TypeError(
                    f"Column '{value_col}' must contain only numeric values"
                )
            try:
                float(value)
            except (TypeError, ValueError, OverflowError) as exc:
                raise TypeError(
                    f"Column '{value_col}' must contain only numeric values"
                ) from exc

    numeric_values = np.array(
        [
            np.nan if is_missing else float(value)
            for value, is_missing in zip(values, missing_values)
        ],
        dtype=float,
    )

    unique_groups = df[group_col].drop_duplicates()
    groups = unique_groups.tolist()
    group_missing = unique_groups.isna().to_numpy()
    group_values = df[group_col]

    means = []
    errors = []

    for group, is_missing in zip(groups, group_missing):
        if is_missing:
            mask = group_values.isna().to_numpy()
        else:
            mask = group_values.eq(group).fillna(False).to_numpy()

        current = numeric_values[mask]
        current = current[~np.isnan(current)]

        if len(current) == 0:
            means.append(np.nan)
            errors.append(0.0)
        else:
            means.append(float(np.mean(current)))
            errors.append(
                float(np.std(current, ddof=1)) if len(current) > 1 else 0.0
            )

    _, ax = plt.subplots()
    x = np.arange(len(groups))
    colors = [COLORS[index % len(COLORS)] for index in range(len(groups))]

    ax.bar(x, means, yerr=errors, color=colors, capsize=4)
    ax.set_xticks(x)
    ax.set_xticklabels(groups)
    ax.set_title(f"Bar chart of {value_col} by {group_col}")
    ax.set_xlabel(group_col)
    ax.set_ylabel(value_col)

    return ax

import re
import os
import glob
import natsort
import pandas as pd


def task_func(directory='./', file_pattern='*.txt', regex=r'([0-9]+)'):
    if not os.path.isdir(directory):
        raise FileNotFoundError(f"Directory not found: {directory}")

    pattern = os.path.join(directory, file_pattern)
    files = [
        path for path in glob.glob(pattern)
        if os.path.isfile(path)
    ]

    if not files:
        raise ValueError(f"No files matching pattern found: {file_pattern}")

    rows = []
    for filepath in natsort.natsorted(files):
        with open(filepath, 'r', encoding='utf-8') as file:
            content = file.read()

        rows.append({
            'Filename': os.path.basename(filepath),
            'Numeric Data': re.findall(regex, content),
        })

    return pd.DataFrame(rows, columns=['Filename', 'Numeric Data'])

