import numpy as np
import random
from datetime import datetime


def task_func(
    rows=3,
    columns=2,
    start_date=datetime(2021, 1, 1),
    end_date=datetime(2021, 12, 31),
    seed=0,
):
    if isinstance(rows, bool) or not isinstance(rows, (int, np.integer)):
        raise TypeError("rows must be a non-negative integer")
    if isinstance(columns, bool) or not isinstance(columns, (int, np.integer)):
        raise TypeError("columns must be a non-negative integer")
    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")

    if not isinstance(start_date, datetime) or not isinstance(end_date, datetime):
        raise TypeError("start_date and end_date must be datetime instances")
    if start_date > end_date:
        raise ValueError("start_date must not be later than end_date")

    total = int(rows) * int(columns)
    start_ordinal = start_date.date().toordinal()
    end_ordinal = end_date.date().toordinal()
    available = end_ordinal - start_ordinal + 1

    if total > available:
        raise ValueError("The date range does not contain enough unique dates")

    rng = random.Random(seed)
    selected_ordinals = rng.sample(range(start_ordinal, end_ordinal + 1), total)

    dates = [datetime.fromordinal(ordinal) for ordinal in selected_ordinals]
    return np.asarray(dates, dtype=object).reshape((int(rows), int(columns)))

