import numpy as np
import math
import matplotlib.pyplot as plt
from scipy.signal import get_window


def task_func(amplitude, frequency, time):
    amplitude_array = np.asarray(amplitude)
    frequency_array = np.asarray(frequency)

    if amplitude_array.ndim != 0 or not np.issubdtype(
        amplitude_array.dtype, np.number
    ):
        raise TypeError("amplitude must be a numeric scalar")

    if frequency_array.ndim != 0 or not np.issubdtype(
        frequency_array.dtype, np.number
    ):
        raise TypeError("frequency must be a numeric scalar")

    try:
        amplitude = float(amplitude)
        frequency = float(frequency)
    except (TypeError, ValueError) as exc:
        raise TypeError(
            "amplitude and frequency must be real numeric scalars"
        ) from exc

    try:
        time = np.asarray(time, dtype=float)
    except (TypeError, ValueError) as exc:
        raise ValueError("time must contain numeric values") from exc

    if time.ndim != 1:
        raise ValueError("time must be a one-dimensional array")

    phase = 2 * math.pi * frequency * time
    wave = amplitude * (
        np.cos(phase).astype(complex) + 1j * np.sin(phase)
    )

    if time.size:
        wave *= get_window("hann", time.size)

    fig, ax = plt.subplots()
    ax.plot(time, wave.real, label="Real Part")
    ax.plot(time, wave.imag, label="Imaginary Part")
    ax.set_title("Complex Wave with Hann Window")
    ax.set_xlabel("Time")
    ax.set_ylabel("Amplitude")
    ax.legend()

    return wave, fig, ax

