import requests
from pathlib import Path
import zipfile
import shutil

# Constants
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")


def task_func(url, filename):
    try:
        destination = DOWNLOAD_DIR / filename

        if destination.is_absolute() or ".." in destination.parts:
            raise ValueError("Invalid filename")

        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)

        response = requests.get(url, stream=True)
        try:
            response.raise_for_status()
            content = response.content
        finally:
            response.close()

        destination.write_bytes(content)

    except requests.exceptions.RequestException as exc:
        return f"Error downloading file: {exc}", []
    except (OSError, TypeError, ValueError) as exc:
        return f"Error handling file: {exc}", []

    try:
        if ZIP_DIR.exists():
            if ZIP_DIR.is_dir():
                shutil.rmtree(ZIP_DIR)
            else:
                ZIP_DIR.unlink()

        ZIP_DIR.mkdir(parents=True, exist_ok=True)
        root = ZIP_DIR.resolve()

        with zipfile.ZipFile(destination, "r") as archive:
            for entry in archive.infolist():
                entry_path = (ZIP_DIR / entry.filename).resolve()
                if entry_path != root and root not in entry_path.parents:
                    raise ValueError("Unsafe ZIP path")

            archive.extractall(ZIP_DIR)

        filenames = [
            path.relative_to(ZIP_DIR).as_posix()
            for path in ZIP_DIR.rglob("*")
            if path.is_file()
        ]

        return "Success: file downloaded and extracted.", filenames

    except (
        OSError,
        ValueError,
        RuntimeError,
        zipfile.BadZipFile,
        zipfile.LargeZipFile,
    ) as exc:
        return f"Error extracting file: {exc}", []

