import pandas as pd
from datetime import datetime
import matplotlib.pyplot as plt
import re
from collections.abc import Mapping

# Constants
ROOMS = ["Room1", "Room2", "Room3", "Room4", "Room5"]


def task_func(date_str, booking_data):
    """Return a room booking status DataFrame and a corresponding bar plot."""

    if not isinstance(date_str, str) or not re.fullmatch(
        r"[0-9]{4}-[0-9]{2}-[0-9]{2}", date_str
    ):
        raise ValueError("date_str must use the YYYY-MM-DD format")

    try:
        requested_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError("date_str must be a valid date") from exc

    if requested_date < datetime.today().date():
        raise ValueError("date_str must not refer to a past date")

    statuses = {room: "Available" for room in ROOMS}

    def normalize_status(status):
        if status is None:
            return "Available"
        if isinstance(status, bool):
            return "Booked" if status else "Available"
        if isinstance(status, str):
            return status.strip() or "Available"
        return str(status)

    def extract_status(value):
        if isinstance(value, Mapping):
            for key in ("status", "booking_status", "Status"):
                if key in value:
                    return value[key]
            return "Available"
        return value

    if isinstance(booking_data, Mapping):
        records = booking_data.items()
        for room, status in records:
            if room in statuses:
                statuses[room] = normalize_status(extract_status(status))
    elif isinstance(booking_data, pd.DataFrame):
        for record in booking_data.to_dict("records"):
            room = record.get("room", record.get("Room", record.get("room_name")))
            if room in statuses:
                status = record.get(
                    "status",
                    record.get("booking_status", record.get("Status")),
                )
                statuses[room] = normalize_status(status)
    elif booking_data is not None:
        for record in booking_data:
            if isinstance(record, Mapping):
                room = record.get(
                    "room", record.get("Room", record.get("room_name"))
                )
                status = record.get(
                    "status",
                    record.get("booking_status", record.get("Status")),
                )
            elif isinstance(record, (tuple, list)) and len(record) >= 2:
                room, status = record[0], record[1]
            else:
                continue

            if room in statuses:
                statuses[room] = normalize_status(status)

    report = pd.DataFrame(
        {
            "Room": ROOMS,
            "Status": [statuses[room] for room in ROOMS],
        }
    )

    status_order = ["Available", "Booked"]
    status_order.extend(
        status for status in report["Status"] if status not in status_order
    )
    status_values = {
        status: index for index, status in enumerate(status_order)
    }

    _, ax = plt.subplots()
    ax.bar(
        report["Room"],
        report["Status"].map(status_values),
    )
    ax.set_xlabel("Room")
    ax.set_ylabel("Booking Status")
    ax.set_title(f"Room Booking Statuses for {date_str}")
    ax.set_yticks(list(status_values.values()))
    ax.set_yticklabels(list(status_values.keys()))

    return report, ax

