import subprocess
import os
import glob
import uuid

# Constants
ARCHIVE_DIR = '/tmp/archive'


def task_func(pattern):
    if not isinstance(pattern, str) or not pattern.strip():
        raise ValueError("pattern must be a non-empty string")

    matched_files = []
    seen = set()

    for path in glob.glob(pattern):
        absolute_path = os.path.abspath(path)

        if (
            absolute_path not in seen
            and os.path.isfile(absolute_path)
            and not os.path.islink(absolute_path)
        ):
            matched_files.append(absolute_path)
            seen.add(absolute_path)

    if not matched_files:
        raise FileNotFoundError(f"No files matched pattern: {pattern}")

    os.makedirs(ARCHIVE_DIR, exist_ok=True)

    archive_file = os.path.join(
        ARCHIVE_DIR,
        f"archive_{uuid.uuid4().hex}.tar.gz",
    )

    command = ["tar", "-czf", archive_file, "--", *matched_files]

    try:
        subprocess.run(
            command,
            check=True,
            capture_output=True,
            text=True,
        )
    except subprocess.CalledProcessError as exc:
        try:
            os.remove(archive_file)
        except OSError:
            pass

        error_message = exc.stderr.strip() if exc.stderr else str(exc)
        raise RuntimeError(
            f"Failed to create archive: {error_message}"
        ) from exc

    for file_path in matched_files:
        try:
            os.remove(file_path)
        except OSError as exc:
            raise RuntimeError(
                f"Archive created, but failed to delete {file_path}"
            ) from exc

    return archive_file

