from itertools import combinations
from random import sample


def task_func(df, tuples, n_plots):
    import pandas as pd
    import matplotlib.pyplot as plt
    from numbers import Integral

    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    if isinstance(n_plots, bool) or not isinstance(n_plots, Integral):
        raise TypeError("n_plots must be a non-negative integer")
    if n_plots < 0:
        raise ValueError("n_plots must be a non-negative integer")

    try:
        row_tuples = list(tuples)
    except TypeError as exc:
        raise TypeError(
            "tuples must be an iterable of row-value tuples"
        ) from exc

    column_count = len(df.columns)

    for row_tuple in row_tuples:
        try:
            tuple_length = len(row_tuple)
        except TypeError as exc:
            raise TypeError(
                "Each item in tuples must be a row-value tuple"
            ) from exc

        if tuple_length != column_count:
            raise ValueError(
                "Each tuple must contain exactly one value for every "
                "DataFrame column"
            )

    filtered_df = df.copy()
    remove_mask = pd.Series(False, index=filtered_df.index)

    for row_tuple in row_tuples:
        row_mask = pd.Series(True, index=filtered_df.index)

        for column_position, value in enumerate(row_tuple):
            column_values = filtered_df.iloc[:, column_position]

            try:
                value_is_missing = bool(pd.isna(value))
            except (TypeError, ValueError) as exc:
                raise TypeError(
                    "Row values must be scalar values"
                ) from exc

            if value_is_missing:
                matches = column_values.isna()
            else:
                matches = column_values.eq(value).fillna(False)

            row_mask = row_mask & matches

        remove_mask = remove_mask | row_mask

    filtered_df = filtered_df.loc[~remove_mask]

    if n_plots == 0 or len(filtered_df.columns) < 2:
        return filtered_df, []

    column_pairs = list(combinations(filtered_df.columns, 2))
    selected_pairs = sample(
        column_pairs,
        min(int(n_plots), len(column_pairs)),
    )

    plots = []
    for x_column, y_column in selected_pairs:
        _, axes = plt.subplots()
        axes.scatter(filtered_df[x_column], filtered_df[y_column])
        axes.set_xlabel(str(x_column))
        axes.set_ylabel(str(y_column))
        plots.append(((x_column, y_column), axes))

    return filtered_df, plots

