import os
from pathlib import Path
import glob
import shutil


def task_func(source_directory: str, target_directory: str):
    source = Path(source_directory)
    target = Path(target_directory)

    if not source.is_dir():
        raise FileNotFoundError(source_directory)

    target.mkdir(parents=True, exist_ok=True)

    extensions = {".txt", ".docx", ".xlsx", ".csv"}
    target_resolved = target.resolve()

    files = []
    for path in source.rglob("*"):
        if not path.is_file() or path.suffix not in extensions:
            continue
        try:
            path.resolve().relative_to(target_resolved)
        except ValueError:
            files.append(path)

    moved_count = 0

    for file_path in files:
        destination = target / file_path.name
        counter = 1

        while destination.exists() or destination.is_symlink():
            destination = target / (
                f"{file_path.stem}-{counter}{file_path.suffix}"
            )
            counter += 1

        shutil.move(str(file_path), str(destination))
        moved_count += 1

    return moved_count

