import re
import math

def task_func(s):
    number_pattern = re.compile(
        r"[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?"
    )

    count = 0
    sqrt_sum = 0.0

    for field in s.split(","):
        value_text = field.strip()
        if number_pattern.fullmatch(value_text):
            value = float(value_text)
            count += 1
            sqrt_sum += math.sqrt(value)

    return {
        "count": count,
        "sqrt_sum": sqrt_sum,
    }

