# Constants
LABELS = ['H\u2082O', 'O\u2082', 'CO\u2082', 'N\u2082', 'Ar']


def task_func(x, y, labels):
    """Create a seaborn heatmap from x and y values labeled by labels."""
    try:
        x_values = np.asarray(x, dtype=float)
        y_values = np.asarray(y, dtype=float)
    except (TypeError, ValueError) as exc:
        raise ValueError("x and y must contain numeric values") from exc

    if x_values.ndim != 1 or y_values.ndim != 1:
        raise ValueError("x and y must be one-dimensional")
    if len(x_values) == 0 or len(y_values) == 0:
        raise ValueError("x and y must not be empty")
    if len(x_values) != len(y_values):
        raise ValueError("x and y must have the same length")
    if not np.isfinite(x_values).all() or not np.isfinite(y_values).all():
        raise ValueError("x and y must contain only finite values")

    try:
        labels = list(labels)
    except TypeError as exc:
        raise ValueError("labels must be a sequence") from exc

    if len(labels) != len(x_values):
        raise ValueError("labels must have the same length as x and y")

    df = pd.DataFrame(
        np.outer(y_values, x_values),
        index=pd.Index(labels, name="y"),
        columns=pd.Index(labels, name="x"),
    )

    ax = sns.heatmap(df)
    ax.set_xlabel("x")
    ax.set_ylabel("y")

    return ax, df

