import pandas as pd
from sklearn.preprocessing import LabelEncoder


def task_func(df, dct, columns=None):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    result = df.copy()
    result = result.replace(dct)

    selected_columns = result.columns if columns is None else columns

    for column in selected_columns:
        if column not in result.columns:
            continue

        series = result[column]

        if (
            pd.api.types.is_object_dtype(series)
            or pd.api.types.is_categorical_dtype(series)
            or pd.api.types.is_bool_dtype(series)
        ):
            encoder = LabelEncoder()
            non_missing = series.notna()

            encoded = series.copy().astype(object)
            if non_missing.any():
                encoded.loc[non_missing] = encoder.fit_transform(
                    series.loc[non_missing].astype(str)
                )

            result[column] = encoded

        elif pd.api.types.is_numeric_dtype(series):
            mean = series.mean()
            std = series.std()

            if pd.isna(std) or std == 0:
                result[column] = 0
            else:
                result[column] = (series - mean) / std

    return result

