def task_func(script_path: str, temp_dir: str) -> str:
    try:
        if not script_path or not os.path.isfile(script_path):
            return "Script execution failed!"

        if not temp_dir:
            return "Script execution failed!"

        script_path = os.path.abspath(script_path)
        temp_dir = os.path.abspath(temp_dir)

        os.makedirs(temp_dir, exist_ok=True)

        if not os.path.isdir(temp_dir) or not os.access(temp_dir, os.W_OK):
            return "Script execution failed!"

        result = subprocess.run(
            [sys.executable, script_path],
            cwd=temp_dir,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
            timeout=30,
        )

        return (
            "Script executed successfully!"
            if result.returncode == 0
            else "Script execution failed!"
        )

    except (OSError, subprocess.SubprocessError, TypeError, ValueError):
        return "Script execution failed!"

import subprocess
import psutil
import time


def task_func(process_name: str) -> str:
    if not isinstance(process_name, str) or not process_name.strip():
        raise ValueError("process_name must be a non-empty string")

    process_name = process_name.strip()
    matching_processes = []

    for process in psutil.process_iter(["name"]):
        try:
            if process.info.get("name") == process_name:
                matching_processes.append(process)
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    if not matching_processes:
        subprocess.Popen([process_name])
        return f"Process not found. Starting {process_name}."

    for process in matching_processes:
        try:
            process.terminate()
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    _, alive_processes = psutil.wait_procs(matching_processes, timeout=3)

    for process in alive_processes:
        try:
            process.kill()
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    subprocess.Popen([process_name])
    return f"Process found. Restarting {process_name}."

