from collections import Counter
import re


def task_func(json_dir_path, word_count):
    if isinstance(word_count, bool) or not isinstance(word_count, int) or word_count < 0:
        raise ValueError("word_count must be a non-negative integer")

    if not isinstance(json_dir_path, (str, bytes, os.PathLike)) or not os.path.isdir(json_dir_path):
        raise ValueError("json_dir_path must refer to an existing directory")

    if word_count == 0:
        return []

    counter = Counter()

    try:
        filenames = sorted(os.listdir(json_dir_path))
    except OSError:
        return []

    for filename in filenames:
        if not filename.endswith(".json"):
            continue

        path = os.path.join(json_dir_path, filename)
        if not os.path.isfile(path):
            continue

        try:
            with open(path, "r", encoding="utf-8") as file:
                data = json.load(file)
        except (OSError, UnicodeError, json.JSONDecodeError):
            continue

        if isinstance(data, str):
            text = data
        elif isinstance(data, dict) and isinstance(data.get("text"), str):
            text = data["text"]
        else:
            continue

        counter.update(re.findall(r"[^\W_]+", text.casefold()))

    return counter.most_common(word_count)

