import numpy as np
from sklearn.cluster import KMeans


def task_func(data, n_clusters=2, random_state=0):
    try:
        data = list(data)
    except TypeError as exc:
        raise ValueError("data must be an iterable of data points") from exc

    if not data:
        raise ValueError("data must not be empty")

    if (
        isinstance(n_clusters, bool)
        or not isinstance(n_clusters, (int, np.integer))
        or not 1 <= n_clusters <= len(data)
    ):
        raise ValueError("n_clusters must be an integer between 1 and len(data)")

    coordinates = []
    for item in data:
        if not hasattr(item, "__len__") or len(item) != 3:
            raise ValueError("each item must contain an identifier and two coordinates")

        try:
            point = [float(item[1]), float(item[2])]
        except (TypeError, ValueError, IndexError) as exc:
            raise ValueError("coordinates must be numeric") from exc

        if not np.all(np.isfinite(point)):
            raise ValueError("coordinates must be finite")

        coordinates.append(point)

    kmeans = KMeans(
        n_clusters=int(n_clusters),
        random_state=random_state,
        n_init=10,
    )
    return kmeans.fit_predict(np.asarray(coordinates, dtype=float))

import pandas as pd
from scipy.stats import pearsonr


def task_func(data):
    if len(data) < 2:
        return float("nan")

    scores = pd.to_numeric(data["score"], errors="coerce")
    grades = data["grade"]

    valid = scores.notna() & scores.ne(float("inf")) & scores.ne(float("-inf")) & grades.notna()
    scores = scores[valid]
    grades = grades[valid]

    if len(scores) < 2:
        return float("nan")

    if isinstance(grades.dtype, pd.CategoricalDtype) and grades.dtype.ordered:
        categories = list(grades.dtype.categories)
    else:
        try:
            categories = sorted(grades.unique())
        except TypeError:
            categories = sorted(grades.unique(), key=lambda value: (type(value).__name__, repr(value)))

    grade_mapping = {category: rank for rank, category in enumerate(categories)}
    encoded_grades = grades.map(grade_mapping)

    if scores.nunique() < 2 or encoded_grades.nunique() < 2:
        return float("nan")

    return float(pearsonr(scores, encoded_grades)[0])

