import requests
import logging


def task_func(repo_url: str) -> dict:
    threshold = 1000

    try:
        response = requests.get(repo_url, timeout=10)
        response.raise_for_status()
    except requests.exceptions.HTTPError as exc:
        error_response = getattr(exc, "response", None)
        status_code = getattr(error_response, "status_code", None)
        headers = getattr(error_response, "headers", {}) or {}
        remaining = headers.get("X-RateLimit-Remaining")

        if status_code in (403, 429) or str(remaining) == "0":
            logging.warning("GitHub API rate limit exceeded.")

        raise
    except requests.exceptions.RequestException:
        raise

    try:
        repository = response.json()
    except requests.exceptions.RequestException:
        raise
    except (ValueError, TypeError) as exc:
        raise requests.exceptions.RequestException(
            "Failed to decode the GitHub API response."
        ) from exc

    if not isinstance(repository, dict):
        raise requests.exceptions.RequestException(
            "GitHub API response is not a repository object."
        )

    try:
        if repository.get("open_issues_count", 0) > threshold:
            logging.warning(
                "Repository has more than %d open issues.", threshold
            )
    except (TypeError, ValueError):
        pass

    return repository

import matplotlib.pyplot as plt
from scipy.optimize import curve_fit


def task_func(X, Y):
    import numpy as np

    def quadratic(x, a, b, c):
        return a * x**2 + b * x + c

    try:
        x_data = np.asarray(X, dtype=float)
        y_data = np.asarray(Y, dtype=float)
    except (TypeError, ValueError) as exc:
        raise ValueError("X and Y must contain numeric values.") from exc

    if x_data.ndim != 1 or y_data.ndim != 1:
        raise ValueError("X and Y must be one-dimensional.")
    if len(x_data) != len(y_data):
        raise ValueError("X and Y must have the same length.")
    if len(x_data) < 3:
        raise ValueError("At least three data points are required.")
    if not np.all(np.isfinite(x_data)) or not np.all(np.isfinite(y_data)):
        raise ValueError("X and Y must contain only finite values.")
    if len(np.unique(x_data)) < 3:
        raise ValueError("X must contain at least three distinct values.")

    try:
        parameters, _ = curve_fit(quadratic, x_data, y_data)
    except (RuntimeError, ValueError, TypeError, OverflowError) as exc:
        raise ValueError("Quadratic fitting failed.") from exc

    _, ax = plt.subplots()
    ax.scatter(x_data, y_data, label="Data")

    x_fit = np.linspace(x_data.min(), x_data.max(), 500)
    ax.plot(x_fit, quadratic(x_fit, *parameters), label="Quadratic fit")

    ax.set_xlabel("X")
    ax.set_ylabel("Y")
    ax.legend()

    return parameters.tolist(), ax

