import re
import os
import glob
from pathlib import Path


def task_func(pattern, directory, extensions):
    if not os.path.isdir(directory):
        raise NotADirectoryError(directory)

    regex = re.compile(pattern, re.IGNORECASE)

    if extensions:
        if isinstance(extensions, str):
            extensions = [extensions]

        allowed_extensions = {
            ext.lower() if ext.startswith(".") else f".{ext.lower()}"
            for ext in extensions
        }
    else:
        allowed_extensions = None

    candidates = {}

    for root, _, filenames in os.walk(directory):
        for filename in filenames:
            path = os.path.abspath(os.path.join(root, filename))

            if (
                allowed_extensions is not None
                and Path(filename).suffix.lower() not in allowed_extensions
            ):
                continue

            real_path = os.path.realpath(path)
            candidates.setdefault(real_path, path)

    matches = []

    for path in sorted(candidates.values()):
        try:
            with open(path, "r", encoding="utf-8", errors="ignore") as file:
                if regex.search(file.read()):
                    matches.append(path)
        except OSError:
            continue

    return {"list": matches}

