# Constants
COLUMNS = ['A', 'B', 'C', 'D', 'E']


def task_func(df: pd.DataFrame, tuples: list, n_plots: int) -> (pd.DataFrame, list):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    missing_columns = [column for column in COLUMNS if column not in df.columns]
    if missing_columns:
        raise ValueError(f"Missing required columns: {missing_columns}")

    if not isinstance(n_plots, int) or isinstance(n_plots, bool) or n_plots < 0:
        raise ValueError("n_plots must be a non-negative integer")

    rows_to_remove = pd.Series(False, index=df.index)

    for values in tuples:
        if not hasattr(values, "__len__") or len(values) != len(COLUMNS):
            raise ValueError(
                f"Each tuple must contain exactly {len(COLUMNS)} values"
            )

        row_matches = pd.Series(True, index=df.index)

        for column, value in zip(COLUMNS, values):
            if pd.isna(value):
                row_matches &= df[column].isna()
            else:
                row_matches &= df[column].eq(value).fillna(False)

        rows_to_remove |= row_matches

    filtered_df = df.loc[~rows_to_remove]
    plots = []

    if not filtered_df.empty:
        for _ in range(n_plots):
            x_column, y_column = sample(COLUMNS, 2)
            plots.append(
                sns.jointplot(
                    data=filtered_df,
                    x=x_column,
                    y=y_column,
                )
            )

    return filtered_df, plots

import os
from flask_mail import Mail


def task_func(app):
    def env_value(name, default=None):
        value = os.getenv(name)
        return default if value is None or not value.strip() else value.strip()

    def env_bool(name, default=False):
        value = env_value(name)
        if value is None:
            return default

        normalized = value.lower()
        if normalized in {"true", "1", "yes", "on"}:
            return True
        if normalized in {"false", "0", "no", "off"}:
            return False

        raise ValueError(f"Invalid boolean value for {name}: {value}")

    port_value = env_value("MAIL_PORT", "25")
    try:
        mail_port = int(port_value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"Invalid port value for MAIL_PORT: {port_value}") from exc

    mail_config = {
        "MAIL_SERVER": env_value("MAIL_SERVER", "localhost"),
        "MAIL_PORT": mail_port,
        "MAIL_USE_TLS": env_bool("MAIL_USE_TLS"),
        "MAIL_USE_SSL": env_bool("MAIL_USE_SSL"),
        "MAIL_USERNAME": env_value("MAIL_USERNAME"),
        "MAIL_PASSWORD": env_value("MAIL_PASSWORD"),
