    }

    if mail_config["MAIL_USE_TLS"] and mail_config["MAIL_USE_SSL"]:
        raise ValueError("MAIL_USE_TLS and MAIL_USE_SSL cannot both be enabled")

    app.config.update(mail_config)
    mail = Mail(app)

