import numpy as np
from scipy import integrate
import matplotlib.pyplot as plt


def task_func(func, x_range=(-2, 2), num_points=1000):
    if not callable(func):
        raise TypeError("func must be callable")

    try:
        if len(x_range) != 2:
            raise ValueError("x_range must contain exactly two endpoints")
    except TypeError as exc:
        raise TypeError("x_range must contain exactly two endpoints") from exc

    start, end = x_range
    try:
        start, end = float(start), float(end)
    except (TypeError, ValueError) as exc:
        raise TypeError("x_range endpoints must be numeric") from exc

    if not np.isfinite(start) or not np.isfinite(end) or start >= end:
        raise ValueError("x_range must define a finite increasing interval")

    if isinstance(num_points, bool) or not isinstance(num_points, (int, np.integer)):
        raise TypeError("num_points must be an integer")
    if num_points <= 1:
        raise ValueError("num_points must be greater than 1")

    x_values = np.linspace(start, end, num_points)

    try:
        result = func(x_values)
    except Exception:
        result = [func(x) for x in x_values]

    try:
        y_values = np.asarray(result, dtype=float)
    except (TypeError, ValueError) as exc:
        raise TypeError("func must return numeric values") from exc

    if y_values.ndim == 0:
        y_values = np.full(x_values.shape, y_values.item())
    elif y_values.ndim != 1 or y_values.size != x_values.size:
        raise ValueError(
            "func must return a scalar or a one-dimensional array matching x"
        )

    if not np.all(np.isfinite(y_values)):
        raise ValueError("func returned NaN or infinite values")

    cumulative_integral = integrate.cumulative_trapezoid(
        y_values, x_values, initial=0
    )

    name = getattr(func, "__name__", "f")
    if not isinstance(name, str) or not name or name == "<lambda>":
        name = "f"

    _, ax = plt.subplots()
    ax.plot(x_values, y_values, label=f"{name}(x)")
    ax.plot(
        x_values,
        cumulative_integral,
        label=f"Cumulative integral of {name}(x)",
    )
    ax.set_xlabel(f"x for {name}")
    ax.set_ylabel(f"{name}(x) and cumulative integral")
    ax.legend()
    ax.grid(True)

    return ax

