import sqlite3
import pandas as pd
import csv
from io import StringIO

# Constants
DATABASE_NAME = 'test.db'
TABLE_NAME = 'test_table'


def task_func(csv_input):
    if isinstance(csv_input, StringIO):
        csv_input.seek(0)
        rows = list(csv.reader(csv_input))
    else:
        with open(csv_input, 'r', encoding='utf-8', newline='') as file:
            rows = list(csv.reader(file))

    if not rows or not rows[0]:
        raise ValueError("CSV input must contain a header row.")

    headers = rows[0]

    if any(header == "" for header in headers):
        raise ValueError("CSV headers must not be empty.")

    if any("\x00" in header for header in headers):
        raise ValueError("CSV headers must not contain null characters.")

    normalized_headers = [header.casefold() for header in headers]
    if len(normalized_headers) != len(set(normalized_headers)):
        raise ValueError("CSV headers must be unique.")

    expected_fields = len(headers)
    data = rows[1:]

    for row_number, row in enumerate(data, start=2):
        if len(row) != expected_fields:
            raise ValueError(
                f"Row {row_number} contains {len(row)} fields; "
                f"expected {expected_fields}."
            )

    def quote_identifier(identifier):
        return '"' + identifier.replace('"', '""') + '"'

    quoted_table = quote_identifier(TABLE_NAME)
    quoted_columns = ", ".join(quote_identifier(header) for header in headers)
    column_definitions = ", ".join(
        f"{quote_identifier(header)} TEXT" for header in headers
    )
    placeholders = ", ".join("?" for _ in headers)

    with sqlite3.connect(DATABASE_NAME) as connection:
        connection.execute(f"DROP TABLE IF EXISTS {quoted_table}")
        connection.execute(
            f"CREATE TABLE {quoted_table} ({column_definitions})"
        )

        if data:
            connection.executemany(
                f"INSERT INTO {quoted_table} ({quoted_columns}) "
                f"VALUES ({placeholders})",
                data,
            )

        return pd.read_sql_query(
            f"SELECT {quoted_columns} FROM {quoted_table}",
            connection,
        )

