import numpy as np
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import mean_squared_error


def task_func(num_samples=1000, k=5, d=2, random_seed=None):
    if isinstance(num_samples, bool) or not isinstance(num_samples, (int, np.integer)):
        raise TypeError("num_samples must be an integer")
    if num_samples <= 0:
        raise ValueError("num_samples must be positive")

    rng = np.random.default_rng(random_seed)
    original = rng.normal(size=num_samples)
    transformed = k * original + d

    standardized = StandardScaler().fit_transform(
        transformed.reshape(-1, 1)
    ).ravel()

    return float(mean_squared_error(transformed, standardized))

import pandas as pd
import os


def task_func(original_file_location="test.xlsx", new_file_location="new_test.xlsx", sheet_name="Sheet1"):
    if not os.path.exists(original_file_location):
        raise FileNotFoundError(original_file_location)

    with pd.ExcelFile(original_file_location) as workbook:
        if sheet_name not in workbook.sheet_names:
            raise ValueError(f"Sheet '{sheet_name}' does not exist")
        data = pd.read_excel(workbook, sheet_name=sheet_name)

    data.to_excel(new_file_location, sheet_name=sheet_name, index=False)

    return pd.read_excel(new_file_location, sheet_name=sheet_name)

import pandas as pd
from collections import Counter

def task_func(d):
    result = {"x": Counter(), "y": Counter(), "z": Counter()}

    for item in d:
        for key in result:
            if key in item:
                result[key][item[key]] += 1

    return result
